// 考题库 - 自动生成于知识库
// 共 237 道题
const questionBank=[
{id:1,competencyId:3,stem:"员工成长3+1阶段模型中，适应期通常对应入职后的哪个时间段？",options:["0-3个月", "3-6个月", "0-1个月", "1-3个月"],answer:0,explanation:"适应期为入职后0-3个月，新人在这个阶段需要快速融入环境和掌握基本技能。"},
{id:2,competencyId:3,stem:"新员工出现「拒绝接电话」「害怕和客户沟通」的表述时，主任应首先判断什么问题？",options:["是否缺乏必要的培训", "是「不会」还是「不敢」", "是否态度问题需要批评", "是否案件分配不合理"],answer:1,explanation:"适应期重点识别「不会」还是「不敢」。「害怕沟通」指向「不敢」，应通过示范沟通和建立小成功经验来建立信心。"},
{id:3,competencyId:3,stem:"16字辅导法的正确执行顺序是什么？",options:["我说你听→我做你看→你做我看→你说我听", "我做你看→我说你听→你做我看→你说我听", "你说我听→我做你看→我说你听→你做我看", "我做你看→你做我看→我说你听→你说我听"],answer:0,explanation:"16字辅导法顺序：我说你听(讲标准)→我做你看(示范)→你做我看(观察)→你说我听(反思)。四步不能颠倒。"},
{id:4,competencyId:3,stem:"四维分类模型包含哪些分析框架？（多选）",options:["业绩×合规", "能力×意愿", "态度×技能", "经验×潜力"],answer:0,explanation:"四维分类模型包含两个分析框架：业绩×合规（评估当前表现），能力×意愿（决定管理策略）。"},
{id:5,competencyId:3,stem:"对于能力弱但意愿高的员工，应采取什么管理策略？",options:["安心授权，给挑战性任务", "重点培养，逐步授权，从简单任务开始配合辅导", "激励动机后授权", "暂不授权，先绩效沟通"],answer:1,explanation:"能力弱但意愿高的员工需要重点培养、逐步授权，从简单任务开始配合辅导以提升能力。"},
{id:6,competencyId:3,stem:"稳定期员工（1年以上）不需要特别关注，让他们自己发挥即可。",options:["正确", "错误"],answer:1,explanation:"错误。稳定期员工可能出现职业疲惫感、隐性跳槽风险，需要关注其成长需求，提供新挑战或新角色。"},
{id:7,competencyId:3,stem:"风险层员工的三次谈话原则中，第三次谈话的核心目标是什么？",options:["再次警告并记录", "给出最终机会", "明确去留决定并做好留痕", "转给其他主任管理"],answer:2,explanation:"三次谈话：第一次了解原因并支持；第二次明确预期和底线；第三次做出明确去留决定，全程留痕。"},
{id:8,competencyId:3,stem:"对新人讲大道理、对老员工管流程细节，都是正确的管理方式。",options:["正确", "错误"],answer:1,explanation:"错误。这是常见误区：对新人应给具体方法示范，对老员工应关注结果和成长方向。"},
{id:9,competencyId:3,stem:"以下哪些行为信号表明员工可能处于风险/平台层？（多选）",options:["业绩持续下滑超过2个月", "频繁请假或迟到早退", "主动承担额外任务", "对团队活动明显疏离", "主动分享经验帮助同事"],answer:0,explanation:"风险信号包括业绩持续下滑、出勤异常、团队疏离。主动承担任务和分享经验是积极信号。"},
{id:10,competencyId:3,stem:"在16字辅导法「你做我看」阶段，应该立即纠正员工的每一个小错误。",options:["正确", "错误"],answer:1,explanation:"错误。应允许员工犯错，先让其完成完整环节，再让其先自我反思，最后针对性纠正关键问题。"},
{id:11,competencyId:3,stem:"成长期（3-12个月）员工最常见的风险苗头是什么？",options:["基本技能不熟练", "自负或抗拒规范", "害怕和客户沟通", "完全无法独立作业"],answer:1,explanation:"成长期员工已掌握基本技能，最常见的问题是产生自负心态或抗拒新的管理规范，需要及时引导。"},
{id:12,competencyId:3,stem:"将所有低绩效员工一律归因为态度问题，是正确的诊断方式。",options:["正确", "错误"],answer:1,explanation:"错误。低绩效有多种根因：能力不足、方法不对、资源不够、意愿问题等。一律归因态度会错过真正需要帮助的员工。"},
{id:13,competencyId:3,stem:"授权三重价值中，对员工而言，有效授权最核心的价值是什么？",options:["减轻工作负担", "从操作工成长为谈判专家，获得信任与成就感", "提升团队整体抗风险能力", "让主任有更多时间做分析"],answer:1,explanation:"对员工而言，授权是最佳激励：从操作工成长为谈判专家，获得信任与成就感。"},
{id:14,competencyId:3,stem:"授权和甩锅的本质区别是什么？",options:["授权给的任务更简单", "授权有目标、过程支持和最终责任在管理者，甩锅是推卸责任", "授权只给老员工，甩锅给新员工", "授权不需要跟进，甩锅需要跟进"],answer:1,explanation:"有效授权有目标、有过程支持、最终责任在管理者。甩锅是推卸责任，员工感到压力和不信任。"},
{id:15,competencyId:3,stem:"以下哪些是管理者不愿授权的常见顾虑？（多选）",options:["怕搞砸——员工出错影响结果", "怕费时——教别人不如自己做", "怕威胁——下属做太好会威胁自己", "怕说不清——不知道怎么清晰交代任务"],answer:0,explanation:"四个顾虑都常见，但都是短期视角。长期看授权是效率投资，员工掌握方法后将大量节省主任时间。"},
{id:16,competencyId:3,stem:"准备度矩阵中，对于能力弱且意愿低的员工应该怎么做？",options:["安心授权给挑战性任务", "重点培养，逐步授权", "激励动机后授权关键任务", "暂不授权，先进行绩效沟通"],answer:3,explanation:"能力弱且意愿低的员工不适合授权。应先进行绩效沟通，明确要求和期望，能力和意愿提升后再考虑授权。"},
{id:17,competencyId:3,stem:"80%原则指的是什么？",options:["只授权80%的工作，保留20%", "如果下属能把这件事做到你期望水平的80%，就值得授权", "授权给80%的员工", "每次授权80%的决策权"],answer:1,explanation:"80%原则：如果下属能把事做到期望水平的80%，就值得授权。剩下20%是员工成长空间和教练的辅导价值。"},
{id:18,competencyId:3,stem:"授权六步法第二步「明确边界与资源」包含哪三个要素？",options:["目标、时间、责任人", "权力边界、资源支持、禁忌红线", "任务描述、完成标准、检查节点", "预算、人力、时间"],answer:1,explanation:"边界三要素：权力边界(500元以内可自判)、资源支持(可协调其他团队)、禁忌红线(绝对禁止人身攻击或违规承诺)。"},
{id:19,competencyId:3,stem:"授权六步法的正确顺序是？",options:["设定目标→明确边界→确定汇报→确认理解→公开宣布→跟进兜底", "确认理解→设定目标→明确边界→确定汇报→公开宣布→跟进兜底", "公开宣布→设定目标→明确边界→确定汇报→确认理解→跟进兜底", "设定目标→确认理解→明确边界→跟进兜底→确定汇报→公开宣布"],answer:0,explanation:"六步法顺序：①设定目标→②明确边界→③确定汇报→④确认理解(让员工复述)→⑤公开宣布→⑥跟进兜底。"},
{id:20,competencyId:3,stem:"授权后就应该完全放手不管，让员工独立完成，这样他们才能真正成长。",options:["正确", "错误"],answer:1,explanation:"错误。授权后完全不管等于甩锅。应建立固定跟进节奏，用教练式提问而非指令性干预。"},
{id:21,competencyId:3,stem:"看到下属做不好授权任务时，应该立即夺回来自己做，以免影响业绩。",options:["正确", "错误"],answer:1,explanation:"错误。这是对授权最大的伤害。应指出风险，用提问引导员工自己找解法，允许80分以上的不完美。"},
{id:22,competencyId:3,stem:"「王磊困局」描述的是什么问题？",options:["王磊不会做数据分析", "王磊每天花2小时审核录音，没时间做核心管理工作", "王磊的团队业绩最差", "王磊不愿意授权给下属"],answer:1,explanation:"「王磊困局」：组长每天花2小时审核录音，导致无暇分析数据、优化策略。审核录音是可授权的重复性工作。"},
{id:23,competencyId:3,stem:"授权六步法中的「公开宣布」这一步可以跳过，私下告诉员工就行。",options:["正确", "错误"],answer:1,explanation:"错误。公开宣布是赋予员工正式权力的关键。在晨会或群里明确宣布，让团队知道「这件事他说了算」。"},
{id:24,competencyId:3,stem:"教练式跟进的三维提问包括哪些方向？（多选）",options:["问卡点——当前遇到的最大困难是什么", "问思考——你试过哪些办法？还有什么想法", "问态度——你为什么做不好", "问行动——接下来你打算如何测试或改进"],answer:0,explanation:"教练式三维提问：问卡点、问思考、问行动。不问态度（容易变指责），用开放式问题引导员工自己找解。"},
{id:25,competencyId:4,stem:"GROW模型的四个步骤按顺序分别是？",options:["Goal→Reality→Options→Will", "Goal→Options→Reality→Will", "Goal→Reality→Will→Options", "Goal→Will→Reality→Options"],answer:0,explanation:"GROW顺序：G目标设定→R现状分析→O方案探索→W行动确认。顺序不能打乱，每个阶段都是下一阶段的基础。"},
{id:26,competencyId:4,stem:"在GROW模型中，会话目标与行动目标的区别是什么？",options:["没有区别，是同一个概念", "会话目标是本次谈话要达成的共识，行动目标是下一周期要达成的具体结果", "会话目标是长期目标，行动目标是短期目标", "会话目标针对个人，行动目标针对团队"],answer:1,explanation:"会话目标=「今天聊完我们要找到什么解决方案」；行动目标=「接下来一周要达到XX元回款承诺」。两个层次都要明确。"},
{id:27,competencyId:4,stem:"GROW的Reality（现状）阶段，以下哪个选项是正确的提问方式？",options:["你为什么业绩这么差", "你知道自己哪里做得不好吗", "目前你的通话数据是怎样的？已经尝试过哪些方法", "你是不是不够努力"],answer:2,explanation:"Reality阶段要问客观事实、已做努力和障碍分析三个维度。避免主观评判，用数据说话。"},
{id:28,competencyId:4,stem:"Reality阶段的三个核心提问维度包括哪些？（多选）",options:["客观事实——当前的具体数据是什么", "已做努力——已经尝试过哪些方法", "障碍分析——遇到的卡点在哪里", "责任追究——是谁导致的这个问题"],answer:0,explanation:"Reality阶段三个维度：客观事实、已做努力、障碍分析。不追问责任归属，聚焦于理清现状。"},
{id:29,competencyId:4,stem:"Options阶段员工说不知道时，应该怎么办？",options:["直接告诉他答案", "先给3秒沉默，再换角度引导，如「如果你必须选一个方向，会是什么」", "跳过Options直接进入Will", "批评他不肯思考"],answer:1,explanation:"「不知道」有四种类型：真不知道/怕说错/敷衍抗拒/认知盲区。用3秒沉默+五种替代问法，或缩小范围到二选一。"},
{id:30,competencyId:4,stem:"Will（行动确认）阶段的四要素是什么？",options:["Who/Why/How/When", "What/When/Check/Support", "Plan/Do/Check/Act", "Goal/Task/Time/Result"],answer:1,explanation:"Will阶段四要素：What(做什么)→When(何时完成)→Check(如何验证)→Support(需要什么支持)。确保行动可追踪。"},
{id:31,competencyId:4,stem:"在Will阶段，用1-10分确认意愿时，员工说5分怎么办？",options:["接受5分，按计划执行", "降到他能接受的程度", "追问：「为什么是5分而不是3分？从5分到7分需要什么条件？」", "放弃辅导，等他有更高意愿再说"],answer:2,explanation:"1-10意愿确认：低于7分时，先正向肯定(为什么不是3分)，再探讨提升条件(到7分需要什么)。确认最低可接受的行动。"},
{id:32,competencyId:4,stem:"GROW辅导时发现员工明显走偏，应该立即给出正确答案，节省时间。",options:["正确", "错误"],answer:1,explanation:"错误。这是GROW常见误区——Options阶段给答案。应引导员工自己想方案，主任的方案不一定适合员工的能力水平。"},
{id:33,competencyId:4,stem:"GROW辅导面谈中跳过Reality直接进入Options是可以接受的，只要最终有行动方案。",options:["正确", "错误"],answer:1,explanation:"错误。跳过R是常见误区。没有充分理清现状，后续的方案会缺乏根基，可能治标不治本。"},
{id:34,competencyId:4,stem:"GROW辅导的三个层次，最高层次（精通）的核心特征是什么？",options:["严格按GROW四步走完流程", "能深挖2-3层找到根因", "员工能产生自我觉察，自己发现问题并制定方案", "使用更多专业术语和工具"],answer:2,explanation:"精通层次：员工能自我觉察，自己发现问题并制定方案。主任不再只是走流程，而是创造让员工自我成长的空间。"},
{id:35,competencyId:4,stem:"在辅导面谈中应该多用封闭式问题，这样效率更高。",options:["正确", "错误"],answer:1,explanation:"错误。GROW辅导应多用开放式问题引导员工思考，封闭式问题只能获得有限信息，不利于员工深度反思。"},
{id:36,competencyId:4,stem:"GROW模型只适用于低绩效员工的辅导，对高绩效员工不适用。",options:["正确", "错误"],answer:1,explanation:"错误。GROW适用于各类绩效水平的员工辅导。高绩效员工同样需要目标设定和成长规划，GROW是通用辅导工具。"},
{id:37,competencyId:4,stem:"现代企业的双轨制职业发展体系包含哪两条并行的通道？",options:["管理通道和销售通道", "管理通道和专业通道", "专业通道和行政通道", "技术通道和运营通道"],answer:0,explanation:"双轨制=管理通道（带团队拿结果）+专业通道（深耕业务成为专家），两条路同等重要、薪资职级对等。"},
{id:38,competencyId:4,stem:"在双轨制中，管理方向的核心变化是什么？",options:["从'会干'到'能总结、能带教、能创新'", "从'自己干好'转变为'通过别人干好'", "从业务思维转变为财务思维", "从短期目标转变为长期战略"],answer:1,explanation:"管理方向的核心变化是从'自己干好'到'通过别人干好'，重心是分配任务、协调资源、辅导下属、提升团队人效。"},
{id:39,competencyId:4,stem:"识别管理方向员工的四个特征不包括以下哪一项？",options:["愿意帮别人成长", "关注团队整体结果", "能扛事有担当", "业务技能在团队中最强"],answer:3,explanation:"识别管理潜力不看业绩高低，而看四个软实力：帮人成长、关注整体、能扛事、有号召力。业务最强不代表适合管理。"},
{id:40,competencyId:4,stem:"对于确认适合走专业路线的绩优员工，以下哪种激励方式最不恰当？",options:["给名分：任命为'疑难案件专项处理人'", "给空间：每周预留2小时研究高难度案件", "给认可：安排月度经验分享会", "给承诺：承诺下次组长竞聘优先考虑"],answer:3,explanation:"对专业型员工，不应该用'以后给你升管理岗'来激励。正确做法是给名分、给空间、给认可——让TA在专业赛道上被看见、有成长。"},
{id:41,competencyId:4,stem:"培养管理方向员工的三步试水法，正确的顺序是什么？",options:["带人体验→短期单项任务→负责小组任务", "短期单项任务→带人体验→负责小组任务", "负责小组任务→带人体验→短期单项任务", "短期单项任务→负责小组任务→带人体验"],answer:1,explanation:"三步试水法从低风险到高风险：①短期单项任务（如主持晨会）→②带人体验（如担任新员工向导）→③负责小组任务（如担任禾苗组长带5-6人）。逐步测试，降低双方风险。"},
{id:42,competencyId:4,stem:"以下哪些是识别专业方向员工的特征？",options:["业务钻得深，喜欢研究复杂案例", "能做但讲不清楚自己的方法", "有强烈的自我要求和高标准", "持续学习，关注行业动态和新技能"],answer:0,explanation:"专业方向四大特征：业务钻得深、能讲清方法、在乎成果质量、持续学习。'能做但讲不清'恰恰说明缺乏专业方向的关键能力——方法论提炼和传授。"},
{id:43,competencyId:4,stem:"IDP（个人发展计划）包含哪些要素？",options:["长期愿景和核心优势", "发展领域和年度目标", "具体行动和所需支持", "评估周期"],answer:0,explanation:"IDP七要素全部正确：长期愿景、核心优势、发展领域、年度目标、具体行动、所需支持、评估周期。核心原则：员工主导，主管支持。"},
{id:44,competencyId:4,stem:"员工在管理试水后想退出，主任的恰当做法包括哪些？",options:["先共情挑战难度，探寻具体原因", "重新定义为'练习'而非'正式任命'，降低心理压力", "建议从更小的尝试开始（如只辅导一个新人一个技能点）", "告诉员工'这是公司的安排，再坚持一下'"],answer:0,explanation:"共情→重新定义→降低门槛，是应对试水退出的三步。强迫员工继续只会加深抗拒，更重要的是尊重员工的自我认知。"},
{id:45,competencyId:4,stem:"在IDP制定中，应该由主管填写好计划，然后让员工签字确认，这样效率最高。",options:["正确", "错误"],answer:1,explanation:"错误。IDP的核心原则是'员工主导、主管支持'——员工自己写的计划才有ownership。主管代填写再让员工签字，员工内心不会真正认同，执行率很低。"},
{id:46,competencyId:4,stem:"专业通道和管理通道是两条并行的发展路径，薪资和职级可以对等，没有高低之分。",options:["正确", "错误"],answer:0,explanation:"正确。双轨制的核心就是打破'只有当官才有前途'的认知——专业线最高职级P3-1薪资与主任对等。不是所有人都适合做管理，也不是只有做管理才有发展。"},
{id:47,competencyId:4,stem:"对于确认不想走管理路线的员工，应该给他更多时间考虑，持续引导他朝管理方向发展。",options:["正确", "错误"],answer:1,explanation:"错误。员工确认不想走管理后，应尊重其选择，肯定其坦诚和专业价值，转而帮他规划专业深化路径。持续引导TA走不想要的路是消耗双方信任。"},
{id:48,competencyId:4,stem:"培养人才即使最终流失了也是值得的，因为管理者积累的培养经验本身就是核心竞争力。",options:["正确", "错误"],answer:0,explanation:"正确。培养人才的目标是打造可持续的'人才供应链'，而非依赖个别明星员工。即使人员流失，管理者积累的人才培养经验是不可逆的资产。"},
{id:49,competencyId:4,stem:"IDP的定期回顾建议节奏是什么？",options:["每周一次正式回顾", "每月一次简短跟进+每季度一次正式回顾", "每年一次全面复盘即可", "只在员工出现问题时才回顾"],answer:1,explanation:"IDP回顾节奏：每月一次10-15分钟简短跟进（在常规1v1中顺带过），每季度一次30分钟正式回顾（全面复盘+动态调整）。频率太低计划会废，频率太高增加双方负担。"},
{id:50,competencyId:4,stem:"张磊业绩优秀但明确表示'不想带人'，从他的行为画像来看——业务钻研深、持续学习、在乎交付质量、但带新人反馈不佳——他更适合哪条发展路径？",options:["管理方向：克服短板，继续培养管理能力", "专业方向：发挥业务钻研优势，走专家路线", "不做选择：同时走两条路，哪个机会好走哪个", "维持现状：不做任何改变，专注做好当前工作"],answer:1,explanation:"张磊的行为画像完全匹配专业方向四大特征（业务深、能总结、重质量、持续学），管理方向特征缺失（帮人成长、关注整体），强推管理会导致双输。"},
{id:51,competencyId:4,stem:"对专业方向员工'给名分'的具体做法包括哪些？",options:["任命为'疑难案件专项处理人'或'内部讲师'", "工位张贴专家岗标识增强身份认同", "在全员场合公开表扬其专业贡献", "承诺年底晋升为组长"],answer:0,explanation:"给名分是通过正式或非正式的头衔和公开认可，让专业人才在非管理路径上获得'身份认同'。承诺升组长恰恰是把TA推回了管理路线。"},
{id:52,competencyId:4,stem:"在能力-意愿矩阵中，'高能力+低意愿'的员工属于什么类型？",options:["明星型：能力强也愿意干", "新人/转型期：愿意干但还不会", "老油条型：能力够但不愿干", "问题型：既不会也不愿干"],answer:2,explanation:"高能力+低意愿=老油条型。他们有足够的能力但缺少动力。培养策略不是加任务或紧盯，而是先找意愿低落的根因，再通过职业对话和意义重构重新激活。"},
{id:53,competencyId:4,stem:"情境领导模型中，对D1阶段（低能力+高意愿）的员工应该采用什么领导风格？",options:["授权式：给方向就放手，定期检查结果", "支持式：少教多问，帮TA自己拿方案", "指令式：说清楚做什么、怎么做、标准是什么", "教练式：给方法+给鼓励，帮TA迈过坎"],answer:2,explanation:"D1（热情的新手，低能力高意愿）需要指令式领导：清晰的步骤、明确的示范、具体的标准。此时用授权式是最大的管理错误——TA还没学会走路就让他跑。"},
{id:54,competencyId:4,stem:"16字辅导法「我做你看」这一步的关键点是什么？",options:["让员工自己摸索，错了再改", "把关键细节放大展示，让员工看到'教科书级'的操作", "快速演示一遍概要就行", "让其他员工代为演示"],answer:1,explanation:"'我做你看'是管理者亲自示范，关键是把关键细节放大——不是敷衍地演示一遍，而是让员工看到每个步骤背后的判断逻辑和关键细节。管理者的示范质量直接决定了员工的学习效果。"},
{id:55,competencyId:4,stem:"表扬的三个层次中，最有效的是哪一个？",options:["泛泛表扬：'干得不错'", "行为表扬：具体行为+效果", "认可+赋予意义：行为+影响+深层意义", "物质表扬：奖金和礼物"],answer:2,explanation:"最有效的是'认可+赋予意义'——不仅说出具体行为和效果，还让员工感受到做的事对团队/客户有更深层的意义。这触达了人的内在动机，效果最持久。"},
{id:56,competencyId:4,stem:"对明星型员工（高能力+高意愿），最合适的培养策略是什么？",options:["加强日常监督和每日数据检查", "给挑战、给舞台、给成长空间——授权重要任务、让TA带新人", "减少TA的工作量，让TA多休息", "保持现状不做任何改变，怕打破现有平衡"],answer:1,explanation:"明星员工的培养策略是：给挑战（让TA做有难度的事）、给舞台（让TA分享经验给团队）、给成长空间（让TA有机会尝试带人/负责项目）。不给成长的明星员工迟早会去别处寻找成长。"},
{id:57,competencyId:4,stem:"16字辅导法的四个步骤按顺序是什么？",options:["我说你听——讲解要点和标准，说清楚'为什么这样做'", "我做你看——管理者亲自示范，放大关键细节", "你做我看——员工动手实践，管理者观察不打断", "你说我听——员工复述总结，检验是否真正理解"],answer:0,explanation:"16字辅导法四步骤顺序为：我说你听→我做你看→你做我看→你说我听。这个顺序不能颠倒——没有示范就直接让员工做是赌博，没有复述确认就结束等于没检验学习效果。"},
{id:58,competencyId:4,stem:"情境领导模型中，对D2阶段（有一定能力+低意愿）的员工，以下哪些做法是正确的？",options:["既给方法也给鼓励，帮TA迈过坎", "了解意愿下降的原因：是遇到挫折了还是看不到价值", "完全放手不管，让TA自己调整", "教练式：分析卡在哪里，针对性地给指导"],answer:0,explanation:"D2（遇到挫折的学习者）需要教练式领导：给方法+给鼓励。关键是要了解挫折背后的原因并针对性解决。完全放手不管会让TA滑向更低状态。"},
{id:59,competencyId:4,stem:"员工处于D4阶段（高能力高意愿）的特征包括哪些？",options:["能独立完成任务，不需要太多指导", "对自己的能力有信心", "遇到问题愿意自己先尝试解决", "需要管理者每天检查每一步操作"],answer:0,explanation:"D4（独立的贡献者）特征是独立、自信、主动。匹配授权式领导：给方向就放手，定期检查结果即可。过度管控（每天检查每一步）是最大的管理错误，会让D4员工感觉不被信任。"},
{id:60,competencyId:4,stem:"同一个员工面对不同任务时，可能处于不同的发展水平阶段，因此需要动态调整领导风格。",options:["正确", "错误"],answer:0,explanation:"正确。情境领导的精髓：一个员工在熟悉的任务上可能处于D4（授权式管理即可），但对一个新任务可能退回到D1（需要指令式辅导）。领导风格不是给'人'贴标签，而是针对'人+任务'的组合动态匹配。"},
{id:61,competencyId:4,stem:"表扬应该越笼统越好，这样员工会有更大的想象空间。",options:["正确", "错误"],answer:1,explanation:"错误。笼统表扬（'干得不错'）几乎无效——员工不知道'好在哪里'，不知道该重复什么行为。表扬必须具体到行为+效果：'你刚才先问客户的困难而不是直接催款，这让客户感受到了尊重并愿意继续沟通'。"},
{id:62,competencyId:4,stem:"对问题型员工（低能力+低意愿），管理者应该投入最多的时间和精力进行培养。",options:["正确", "错误"],answer:1,explanation:"错误。对问题型员工，首先判断'是否可挽救'。如果能力可培养但意愿低，设定明确的改善计划和硬性节点；如果属于岗位错配，与其持续投入低效培养，不如坦诚讨论岗位匹配问题。管理者不应把80%精力放在20%的低效人员上。"},
{id:63,competencyId:4,stem:"员工分类是一次性工作，做好了可以一直沿用。",options:["正确", "错误"],answer:1,explanation:"错误。员工阶段是动态变化的：新人从D1逐步成长到D2-D3-D4，老员工也可能因为遇到挫折或变化从D4滑到D2。建议每个季度重新做一次团队盘点，更新每个人的阶段标签。"},
{id:64,competencyId:4,stem:"新人上岗带教四个阶段的正确顺序是？",options:["准备期→基础带教期→独立实践期→稳定成长期", "基础带教期→准备期→独立实践期→稳定成长期", "准备期→独立实践期→基础带教期→稳定成长期", "基础带教期→准备期→稳定成长期→独立实践期"],answer:0,explanation:"四阶段顺序：①准备期(第1周)→②基础带教期(第2-4周)→③独立实践期(第2-3月)→④稳定成长期(第4-6月)。"},
{id:65,competencyId:4,stem:"基础带教期的渐进式放手比例是多少？",options:["第1周50%→第2周70%→第3周100%", "第2周20%→第3周50%→第4周70%", "第1周30%→第2周60%→第3周90%", "第2周10%→第3周30%→第4周50%"],answer:1,explanation:"渐进式放手：第2周独立通话20%→第3周50%→第4周70%。逐步增加自主权，让新人有适应过程。"},
{id:66,competencyId:4,stem:"红黄牌机制中，黄牌代表什么？",options:["警告，两次黄牌会被辞退", "可犯错教学的机会，做错了正是教学时刻", "需要扣绩效分", "需要上报上级处理"],answer:1,explanation:"黄牌=可犯错教学的机会，做错了正是最好的教学时刻。红牌=零容忍行为(如合规红线、客户信息泄露等)，一次即严处。"},
{id:67,competencyId:4,stem:"以下哪些是新人30天陪跑检核表的关键节点？（多选）",options:["Day1：环境融入、认识团队、了解基本规范", "Day3：掌握系统基本操作", "Day7：首次独立完成简单案件跟进", "Day15：第一次正式绩效面谈", "Day30：完成转正评估"],answer:0,explanation:"30天陪跑有11个节点。Day15不是正式绩效面谈而是检查点回顾。Day30是月度回顾而非转正评估（转正在2-3月）。"},
{id:68,competencyId:4,stem:"转正评估的四维标准中，业务维度的达标标准是什么？",options:["回收率达到团队均值", "回收率达到团队均值的80%以上", "回收率达到团队均值的90%以上", "回收率达到团队前50%"],answer:1,explanation:"转正业务维度标准：回收率达到团队均值的80%以上。其他维度：合规(无重大违规)、能力(能独立处理常规案件)、态度(积极主动)。"},
{id:69,competencyId:4,stem:"新人带教中最容易出现落差感的是哪个阶段？",options:["准备期（第1周）", "基础带教期（第2-4周）", "独立实践期（第2-3月）", "稳定成长期（第4-6月）"],answer:2,explanation:"独立实践期(第2-3月)是落差期高发阶段。新人开始独立面对困难，发现理想与现实差距，需要主任特别关注心态变化。"},
{id:70,competencyId:4,stem:"新人第一天到岗就应该开始打电话，尽快进入工作状态。",options:["正确", "错误"],answer:1,explanation:"错误。第一天应聚焦环境融入、角色认知、基本规范和师徒配对。直接打电话会让新人感到压力和混乱，反而延长适应期。"},
{id:71,competencyId:4,stem:"3个月后新人已经独立，主任可以完全放手，把精力转移到其他新人身上。",options:["正确", "错误"],answer:1,explanation:"错误。3个月不是终点。稳定成长期(4-6月)需要习惯固化、能力进阶和帮带他人的机会，主任仍需关注和引导。"},
{id:72,competencyId:4,stem:"选择带教师傅的五个标准不包括以下哪一项？",options:["业务能力强，话术规范", "有耐心，愿意教", "与新人同乡或同校", "沟通表达能力强", "有正向价值观"],answer:2,explanation:"师傅五标准：①业务能力强话术规范②有耐心愿意教③沟通表达能力强④有正向价值观⑤有一定管理意愿。同乡不是选择标准。"},
{id:73,competencyId:4,stem:"黄牌行为做错了应该严厉批评，让新人记住教训。",options:["正确", "错误"],answer:1,explanation:"错误。黄牌是可犯错教学的机会，做错了正是最好的教学时刻。用16字辅导法引导反思，而不是严厉批评打击信心。"},
{id:74,competencyId:4,stem:"基础带教期的反馈频率应该是？",options:["每天1次", "每2天1次正式反馈+每周2次谈心", "每周1次", "每月1次正式面谈"],answer:1,explanation:"基础带教期(第2-4周)：每2天至少1次正式反馈+每周2次非正式谈心。高频反馈确保新人在关键时刻得到及时指导。"},
{id:75,competencyId:4,stem:"对所有新人应该采用统一的带教节奏，保证公平。",options:["正确", "错误"],answer:1,explanation:"错误。新人学习速度快慢不同，应因材施教。进度快可加速放手，进度慢要增加陪练时间。一刀切节奏是常见误区。"},
{id:76,competencyId:4,stem:"GROW模型的四个阶段按顺序是什么？",options:["Goal目标→Reality现状→Options方案→Will行动", "Reality现状→Goal目标→Will行动→Options方案", "Goal目标→Options方案→Reality现状→Will行动", "Options方案→Reality现状→Goal目标→Will行动"],answer:0,explanation:"GROW模型顺序：Goal（你想达到什么？）→ Reality（现在是什么情况？）→ Options（你有什么选择？）→ Will（你将做什么？）。这个顺序不能颠倒，没搞清楚目标和现状就去讨论方案是无效的。"},
{id:77,competencyId:4,stem:"在GROW辅导中，管理者提问和给建议的时间比例应该是多少？",options:["50%提问，50%给建议", "20%提问，80%给建议", "80%提问，20%给建议", "不提问，直接给建议最高效"],answer:2,explanation:"教练式辅导的核心是：让员工自己说出答案（远比直接告诉TA答案更有力量）。因此80%时间用来提问引导，20%时间给建议补充。如果你在辅导中说的时间超过一半，你就进入了说教模式。"},
{id:78,competencyId:4,stem:"当员工在GROW辅导中说'我不知道'时，以下哪种应对方式最恰当？",options:["立刻自己给出答案，节省时间", "先判断是哪种类型的'不知道'——真不知道、怕说错、敷衍抗拒、还是认知盲区", "换一个更简单的目标重新走GROW流程", "结束辅导，让员工自己想清楚了再来"],answer:1,explanation:"'我不知道'至少要区分为四种类型：真不知道（缩小范围继续引导）、怕说错（建立安全感）、敷衍抗拒（暂停辅导先处理关系）、认知盲区（给一个示范打开思路）。不区分类型直接给答案或放弃，都错失了辅导时机。"},
{id:79,competencyId:4,stem:"'纠错式辅导'和'教练式辅导'的核心区别是什么？",options:["纠错式更高效，教练式太浪费时间", "纠错式是告知答案（管理者输出），教练式是激发思考（员工输出）", "纠错式适用于所有人，教练式只适用于高管", "两者没有本质区别，只是叫法不同"],answer:1,explanation:"核心区别：纠错式=管理者输出答案（'你应该这样做'），教练式=激发员工产出答案（'你觉得应该怎么做'）。纠错式短期见效快但员工依赖性强，教练式短期慢但长期培养员工独立解决问题的能力。"},
{id:80,competencyId:4,stem:"正面反馈三步法的正确顺序是什么？",options:["表达认可→描述行为→说明影响", "描述具体行为→说明正面影响→表达认可/鼓励延续", "说明影响→表达认可→描述行为", "先给奖金→再说明原因→最后鼓励"],answer:1,explanation:"正面反馈三步法：1)描述具体行为（'你昨天处理投诉时先让客户把话说完'），2)说明正面影响（'这让客户感受到了被尊重'），3)表达认可（'这个做法值得保持'）。先有事实再有评价，才有说服力。"},
{id:81,competencyId:4,stem:"辅导的三个层次从低到高依次是什么？",options:["纠错式辅导：发现问题→指出错误→要求改正", "方法式辅导：发现不足→给方法→示范→练习", "教练式辅导：提问激发→引导自悟→自主行动", "放任式辅导：发现不足→等待员工自行发现和改善"],answer:0,explanation:"三个层次：纠错式（指出问题，给答案）→方法式（给方法+示范+练习）→教练式（提问激发让员工自己找到答案）。'放任式'不是辅导而是缺位。"},
{id:82,competencyId:4,stem:"员工说'我不知道'时，可能属于哪些类型？",options:["真不知道——确实没想法，属于知识盲区", "怕说错——有想法但不敢说，需要建立安全感", "敷衍抗拒——不想参与，被动应付，需要先处理关系", "认知盲区——不知道自己不知道，需要示范打开思路"],answer:0,explanation:"四种类型全部正确。判断关键字：真不知道（缩小范围问）、怕说错（'没有对错，先发散'）、敷衍抗拒（暂停辅导先修复关系）、认知盲区（给示范再回来问）。"},
{id:83,competencyId:4,stem:"对于D1阶段（低能力高意愿）的新人，辅导应该侧重于哪些层次？",options:["多使用方法式辅导：给明确的示范和方法", "多用教练式辅导：提问让TA自己思考", "逐步从方法式过渡到教练式：先给足方法打好基础", "完全放手让TA自己摸索"],answer:0,explanation:"D1新人需要更多的方法式辅导（给方法+给示范），到了D2-D3阶段再逐步增加教练式提问的比例。教练式辅导有一个前提——员工具备一定的知识和能力基础，否则'你觉得呢'只会得到'我不知道'。"},
{id:84,competencyId:4,stem:"负面反馈应该在公开场合进行，以让更多人汲取教训。",options:["正确", "错误"],answer:1,explanation:"错误。正面反馈对于值得推广的行为可以公开进行，但负面反馈（纠错）应该私下进行、具体化、对事不对人。公开的负面反馈会激活防御心理，让员工把注意力从'改进行为'转移到'维护面子'上。"},
{id:85,competencyId:4,stem:"每次辅导结束前，应该让员工用自己的话总结今天辅导的关键结论和下一步行动。",options:["正确", "错误"],answer:0,explanation:"正确。辅导收尾必须让员工复述总结，确认理解和行动。如果员工说不出来或说不对，说明辅导没有真正被吸收。这个环节花费的30秒可能是整个辅导最高ROI的30秒。"},
{id:86,competencyId:4,stem:"辅导后不需要追踪，因为员工已经是成年人了，应该对自己的成长负责。",options:["正确", "错误"],answer:1,explanation:"错误。辅导不是一次性的谈话而是'辅导→实践→检查→再辅导'的持续循环。辅导后必须有追踪——每日快检关键行为、每周复盘辅导重点、每月评估能力变化。追踪本身就是辅导的一部分。"},
{id:87,competencyId:4,stem:"好的辅导者在辅导对话中应该把话语权交给员工，让员工说话的比例超过50%。",options:["正确", "错误"],answer:0,explanation:"正确。如果你在辅导中说的时间超过一半，你就从'辅导者'变成了'说教者'。有效的辅导是激发员工思考、让员工产出答案的过程——员工话语权越高，获得感越强。"},
{id:88,competencyId:7,stem:"根据课程提出的'三层激励模型'，最底层的基础保障层是什么？",options:["成长可见层——让每个人看到自己的未来", "社会连接层——把团伙变成真正的团队", "即时反馈层——让每个人每天都知道自己'赢了'", "薪酬福利层——基础的物质激励保障"],answer:2,explanation:"三层激励模型从底到顶依次为：即时反馈层（基础保障）、社会连接层（团队粘合剂）、成长可见层（终极燃料）。即时反馈层让每个人每天都知道自己'赢了'，是激励的地基。"},
{id:89,competencyId:7,stem:"'回款时刻'播报工具的最佳使用时机是什么？",options:["每天下班前做全天总结时", "每天11点、15点等工作状态低迷的时间段", "每周周会上进行总结时", "每天早上的晨会上"],answer:1,explanation:"'回款时刻'播报的最佳时机是每天11点、15点等工作状态较为低迷的时间段，全员停下30秒，播报回款+鼓掌，起到提神和激励的双重作用。"},
{id:90,competencyId:7,stem:"即时反馈必须满足三个条件，以下哪项不是这三个条件之一？",options:["即时——最好当天，绝对不过夜", "具体——不是'干得好'，而是'刚才那句反问太漂亮了'", "物质——必须有奖金或礼品作为载体", "公开——让所有人都知道他的优秀"],answer:2,explanation:"即时反馈的三个条件是：即时、具体、公开。零成本即时反馈不需要物质载体，靠的是'被看见'的力量。"},
{id:91,competencyId:7,stem:"'互助债务'制度的心理学原理是什么？",options:["破窗效应——小问题不处理会引发大问题", "富兰克林效应——让别人帮你，反而会让他更喜欢你", "马太效应——强者越强、弱者越弱", "鲶鱼效应——引入竞争激发活力"],answer:1,explanation:"富兰克林效应指出：让别人帮你一个忙，反而会让他更喜欢你。'互助债务'制度利用这个原理，让团队成员之间形成你来我往的互助关系网，建立'战友'式连接。"},
{id:92,competencyId:7,stem:"根据课程，员工离职的真正原因90%是什么？",options:["钱太少", "工作太累", "看不到自己在这里的未来", "与同事关系不好"],answer:2,explanation:"课程指出：员工离职的真正原因，90%不是钱少，而是'我看不到自己在这里的未来'。这也是第三层'成长可见层'如此重要的原因——给员工一个未来，他们才会给你一个现在。"},
{id:93,competencyId:7,stem:"'教科书式操作'复盘的核心价值是什么？",options:["给表现好的员工发奖金", "让优秀被看见、被命名、被传承", "给落后的员工施加压力", "完成公司的培训考核要求"],answer:1,explanation:"'教科书式操作'复盘的做法是：每天选一通录音，拆解亮点并命名（如'张三反杀法'），让优秀被看见、被命名、被传承。这比笼统的表扬有效得多。"},
{id:94,competencyId:7,stem:"以下哪项是正确的公开表扬方式？",options:["走到身边说'小松，不错啊！可以的！'", "在周会总结时说'大家这个月都辛苦了'", "让全员停下，具体说明某员工的技巧亮点，并让大家鼓掌", "私下在微信上发'干得漂亮'"],answer:2,explanation:"正确的表扬要满足三个条件：具体（说明什么技巧好）、公开（让所有人都知道）、即时。正确的做法是：让全员停下，具体拆解其技巧亮点，命名技能，并让大家鼓掌。"},
{id:95,competencyId:7,stem:"A组长团队3个月留存率62%，B组长91%。以下哪项不是A组长最可能犯的错误？",options:["只看结果，不看过程", "只有惩罚，没有反馈", "给员工提供了过多的成长机会", "自己干所有事，不相信组员"],answer:2,explanation:"A组长的三大致命错误是：1）只看结果不看过程；2）只有惩罚没有反馈；3）自己干所有事。'提供过多成长机会'不是错误，反而是B组长的优势做法。"},
{id:96,competencyId:7,stem:"四个零成本即时反馈工具包括哪些？",options:["'回款时刻'播报——每天低迷时段全员停30秒播报回款加鼓掌", "'难度积分榜'——按案件难度系数计分排名", "'绩效奖金池'——根据业绩排名分配奖金", "'情绪救济券'——每人每周2张，打完憋屈电话可出去走5分钟"],answer:0,explanation:"四个零成本即时反馈工具是：回款时刻播报、难度积分榜、教科书式操作复盘、情绪救济券。'绩效奖金池'涉及金钱，不属于零成本工具。"},
{id:97,competencyId:7,stem:"关于'小师父'认证制度，以下说法正确的是？",options:["单项技能前3名自动成为'小师父'", "新人遇到该类型问题，找小师父现场教学", "小师父需要额外发放岗位津贴", "小师父制度实现了教学相长、减轻组长负担"],answer:0,explanation:"小师父认证是零成本头衔：单项前3自动认证，新人遇问题找小师父教学，好处是教学相长+减轻组长负担。不需要额外发放津贴——这正是'零成本'的核心。"},
{id:98,competencyId:7,stem:"激励的本质是什么？",options:["给好处——用金钱和物质交换员工的努力", "造意义——让员工感觉'被看见、被需要、在成长'", "即时反馈让工作不再是'无声的重复劳动'", "成长可见让员工看到自己在这里的未来"],answer:1,explanation:"激励的本质不是'给好处'，而是'造意义'。具体包括：被看见（即时反馈）、被需要（社会连接）、在成长（成长可见）。金钱激励的边际效应极低，200块绩效抵不过一句'被理解'。"},
{id:99,competencyId:7,stem:"'角色互换日'的做法是每月半天，让组员当组长主持工作，组长去打电话。",options:["正确", "错误"],answer:0,explanation:"正确。角色互换日是第二层社会连接层的工具之一：每月半天，组员当组长主持晨会、分配任务、处理突发，组长去打电话。效果是互相理解对方的难处。"},
{id:100,competencyId:7,stem:"在零预算约束下，管理者无法做任何有效的团队激励。",options:["正确", "错误"],answer:1,explanation:"错误。三层激励模型中的所有工具——即时反馈（回款播报、操作复盘、情绪救济券）、社会连接（互助债务、角色互换、团队信物）、成长可见（技能树、前后对比、小师父）——全部零成本。"},
{id:101,competencyId:7,stem:"'三个月前vs现在'录音对比，是帮助员工看到自己成长的有效方式。",options:["正确", "错误"],answer:0,explanation:"正确。入职时录模拟电话，三个月后对比真实通话录音——这种直观的'成长可见'是最强的自我激励方式，员工自己听完后往往比任何表扬都更受触动。"},
{id:102,competencyId:7,stem:"以下哪项描述最准确地概括了建设性冲突的核心特点？",options:["对人不对事，伴随情绪攻击和关系破坏", "对事不对人，聚焦问题本身，推动思想碰撞与团队成长", "管理者与员工之间的权力对抗", "团队中因个人恩怨产生的矛盾"],answer:1,explanation:"建设性冲突的核心特点是'对事不对人'——聚焦问题本身，通过观点碰撞激发创新思路，暴露潜在风险，推动团队深度思考与共同成长。破坏性冲突才是'对人不对事'。"},
{id:103,competencyId:7,stem:"在托马斯-吉尔曼模型（TKI）中，'高坚持、高合作'对应的是哪种冲突处理策略？",options:["竞争策略", "妥协策略", "合作策略", "回避策略"],answer:2,explanation:"合作策略位于TKI模型的右上角，代表高坚持己见+高合作意愿，追求双赢共赢。通常用于团队策略调整、方案共创等需要共识落地的场景。"},
{id:104,competencyId:7,stem:"质检规则更新必须强制执行，这种场景最适合采用哪种冲突处理策略？",options:["退让策略", "回避策略", "妥协策略", "竞争策略"],answer:3,explanation:"竞争策略（高坚持、低合作）适用于制度宣导等不可协商场景——如质检规则更新、合规红线等，必须以个人意愿为主，不需要征求对方同意。"},
{id:105,competencyId:7,stem:"非暴力沟通四要素的正确顺序是什么？",options:["感受→观察→请求→需要", "观察→感受→需要→请求", "需要→感受→观察→请求", "观察→需要→感受→请求"],answer:1,explanation:"非暴力沟通四部曲的顺序是：观察（客观陈述事实）→感受（坦诚表达情绪）→需要（明确核心诉求）→请求（提出具体可执行的建议）。"},
{id:106,competencyId:7,stem:"以下哪句话最符合非暴力沟通中'观察'的要求？",options:["你怎么回事，业绩一直这么差", "你过去几个月业绩在Top30，本月下滑至后60%-70%", "你是不是不想干了", "我对你很失望"],answer:1,explanation:"观察要求客观陈述事实，避免主观评判。'过去几个月在Top30，本月下滑至后60%-70%'是以数据为依据的事实陈述。其他选项都含有主观评判和情绪推断。"},
{id:107,competencyId:7,stem:"在ABC理性思维重构法中，B代表什么？",options:["行为（Behavior）——我们的具体行动", "信念（Belief）——我们对事件的看法和解释", "平衡（Balance）——理性与感性的平衡", "基础（Base）——压力管理的底层逻辑"],answer:1,explanation:"ABC理论中：A是事件（Activating event），B是信念（Belief）——对事件的看法和解释，C是后果（Consequence）——产生的情绪和行为。核心观点是：压力不是来自事件本身，而是来自B（对事件的看法）。"},
{id:108,competencyId:7,stem:"某主任因多名组员离职而陷入'是我能力太差留不住人'的自我否定，按ABC理论，这属于什么？",options:["对A（事件）的客观认知", "B（信念）中的非理性思维", "C（后果）中的合理反应", "有效的自我反思"],answer:1,explanation:"'是我能力太差留不住人'是非理性信念（B）。理性信念应该是'人员流动是业务团队常态，应分析原因并建立预防机制'。同样的A（人员离职），不同的B（信念），产生完全不同的C（后果）。"},
{id:109,competencyId:7,stem:"时间管理四象限中，管理者应该把60%-80%的精力投入到哪个象限？",options:["紧急且重要（救火区）", "重要不紧急（规划区）", "紧急不重要（授权区）", "不紧急不重要（消耗区）"],answer:1,explanation:"重要不紧急（规划区）的事务——如团队培训体系搭建、业务流程优化、人才梯队培养、长期目标规划——是决定团队和个人长期发展的关键，应投入60%-80%的精力。"},
{id:110,competencyId:7,stem:"托马斯-吉尔曼模型中的五种冲突处理策略包括哪些？",options:["竞争策略——高坚持、低合作", "合作策略——高坚持、高合作，追求双赢", "攻击策略——主动发起冲突以占据优势", "回避策略——低坚持、低合作，暂时搁置问题"],answer:0,explanation:"TKI模型的五种策略是：竞争、合作、妥协、回避、退让。'攻击策略'不是TKI模型中的标准策略。"},
{id:111,competencyId:7,stem:"非暴力沟通中'请求'的要求包括哪些？",options:["以命令句式提出要求，确保对方执行", "以问句形式提出，如'要不要我们一起看看？'", "提出具体、可执行的建议", "请求应该是开放式的，允许对方表达意见"],answer:1,explanation:"请求应以问句形式提出具体可执行的建议，开放地允许对方表达意见。命令句式（'你今天开始必须做到XX'）不符合非暴力沟通中'请求'的本意。"},
{id:112,competencyId:7,stem:"根据课程内容，管理者常见的四大压力源包括哪些？",options:["业绩压力——排名落后带来的冲击", "人员管理压力——请假、摆烂、离职等频发", "技术更新压力——系统迭代频繁", "情绪内耗压力——组员低迷、客户情绪传递、自我怀疑"],answer:0,explanation:"四大压力源是：业绩压力、人员管理压力、角色转变压力、情绪内耗压力。'技术更新压力'不是课程中列出的核心压力源。"},
{id:113,competencyId:7,stem:"当员工情绪激动、暂不适合沟通时，管理者应该采用回避策略，等当事人冷静后再处理。",options:["正确", "错误"],answer:0,explanation:"正确。回避策略（低坚持、低合作）适用于当事人情绪不稳定、暂不适合沟通的场景。这不是逃避问题，而是选择对的时机再沟通。"},
{id:114,competencyId:7,stem:"冲突都是负面的，优秀的管理者应该想办法消灭团队中的一切冲突。",options:["正确", "错误"],answer:1,explanation:"错误。冲突本身并无绝对好坏，分为建设性冲突和破坏性冲突。管理者的核心任务是激发建设性冲突（对事不对人）、抑制破坏性冲突（对人不对事），而非消灭一切冲突。"},
{id:115,competencyId:7,stem:"在ABC理论中，导致压力和情绪困扰的根本原因是事件本身，而非我们对事件的看法。",options:["正确", "错误"],answer:1,explanation:"错误。ABC理论的核心观点恰恰相反——导致情绪困扰的不是事件本身（A），而是我们对事件的看法和信念（B）。同一事件，不同的信念会产生截然不同的情绪和行为结果。"},
{id:116,competencyId:6,stem:"PDCA循环中，A（Action）阶段的核心任务是什么？",options:["重新制定新的计划进入下一循环", "将有效做法标准化、预防复发，无效的重新进入PDCA", "向领导汇报问题解决结果", "对相关责任人进行考核评估"],answer:1,explanation:"A-Action阶段是PDCA闭环的关键：有效的做法标准化（写入流程、变成团队习惯）、分享化（把经验分享给团队）、预防化（从源头防止复发）。无效的做法则重新进入下一轮PDCA。"},
{id:117,competencyId:6,stem:"在问题解决方案制定中，「对症下药」指的是什么？",options:["针对症状快速制定处理措施", "方案必须直接针对根因而非表面现象", "对不同的员工使用不同的解决方案", "同时解决所有相关问题"],answer:1,explanation:"'对症下药'是指解决方案必须直接针对根因设计，而非处理表面现象。如果根因是培训缺失但方案是加强监督，那就是'药不对症'。"},
{id:118,competencyId:6,stem:"PDCA循环中，P（Plan）阶段的第一步是什么？",options:["头脑风暴解决方案", "制定详细的行动计划", "明确问题表现与影响范围", "设定SMART改善目标"],answer:2,explanation:"P阶段的第一步是明确问题——把问题的具体表现说清楚、确定问题影响的有多大范围、问题存在了多久、不解决会有什么后果。还没搞清楚问题是什么就急着找方案，是很多管理者常犯的错误。"},
{id:119,competencyId:6,stem:"在C（Check）阶段，除了检查目标达成度，还应该检查什么？",options:["只检查目标是否达成即可", "检查执行质量、意外效果和人员反馈", "只检查执行人是否按要求做了", "只检查时间节点是否按时完成"],answer:1,explanation:"C阶段需要四个维度的检查：目标达成度（数据OK吗？）、执行质量（动作到位吗？）、意外效果（有没有意外的正/负面效果？）、人员反馈（相关人员的真实感受如何？）。"},
{id:120,competencyId:6,stem:"管理者在制定问题解决方案时，最常遗漏的关键动作是什么？",options:["向团队宣布方案", "将方案写在PPT里", "跟执行人确认方案的可执行性", "在周报中记录方案内容"],answer:2,explanation:"管理者自己想的方案，如果没跟执行人确认可执行性就直接布置，执行失败率高。让执行的人参与方案制定，'自己想的方案自己执行'效果最好。"},
{id:121,competencyId:6,stem:"PDCA循环的四个阶段是什么？",options:["Plan（计划）：明确问题、设定目标、制定方案", "Do（执行）：按计划推进、保留执行记录", "Check（检查）：对比数据、确认目标达成度", "Punish（处罚）：对执行不力的人员进行问责"],answer:0,explanation:"PDCA四个阶段是Plan（计划）、Do（执行）、Check（检查）、Action（行动/固化）。没有Punish（处罚）这个阶段，PDCA是一个改进循环，不是问责循环。"},
{id:122,competencyId:6,stem:"在A-Action阶段，'标准化'包含哪些动作？",options:["把验证有效的做法写入团队流程文档", "让做法变成团队的肌肉记忆而非一次性的经验", "把问题责任人追加到绩效考核中扣分", "如果做法在某个场景有效，要求所有场景都执行"],answer:0,explanation:"标准化是：把验证有效的做法固化为流程、SOP、检查清单等，变成团队的肌肉记忆。'追责扣分'不是标准化的内容；'不分场景一刀切执行'也不是标准化，而是僵化。"},
{id:123,competencyId:6,stem:"执行行动计划时，应该明确哪些要素？",options:["谁来做（负责人）", "做什么（具体任务）", "什么时候完成（时间节点）", "需要什么资源和怎么检查"],answer:0,explanation:"一个完整的行动计划必须包含：谁来做、做什么、做到什么标准、什么时候完成、需要什么资源、怎么检查。这六个要素缺一个，执行就可能跑偏。"},
{id:124,competencyId:6,stem:"问题解决完成后，管理者的工作就结束了，追踪是执行者自己的事。",options:["正确", "错误"],answer:1,explanation:"错误。解决完不等于闭环。管理者的工作在A-Action阶段才真正展现价值——把解决方案标准化防止复发、验证30天后是否还有复发苗头。追踪本身也是问题解决循环的一部分。"},
{id:125,competencyId:6,stem:"PDCA是一次性的问题解决流程，走完一遍问题就彻底解决了。",options:["正确", "错误"],answer:1,explanation:"错误。PDCA是循环，不是一次性的。解决完一个问题，应该马上启动下一个改进循环。而且有些问题第一轮PDCA效果不理想，需要多轮循环才能彻底解决。"},
{id:126,competencyId:6,stem:"在D-Do执行阶段，如果发现了新的问题，应该立即中断当前计划去处理新问题。",options:["正确", "错误"],answer:1,explanation:"错误。执行过程中发现新问题是好事（说明你在认真追踪），但不应立即中断当前计划——除非新问题是重大风险。新问题应该记录下来，等当前PDCA循环走完后再排入下一轮。频繁切换焦点会导致所有问题都解决不到位。"},
{id:127,competencyId:6,stem:"制定解决方案时，应该集中精力在可控因素上，对不可控因素制定'应对策略'而非'解决方案'。",options:["正确", "错误"],answer:0,explanation:"正确。区分可控与不可控是管理者制定方案的重要能力。对于政策变化、外部市场环境等不可控因素，制定'应对策略'（做最坏打算、预备方案）；对于话术、流程、培训等可控因素，制定'解决方案'（可以彻底改变的）。"},
{id:128,competencyId:6,stem:"问题识别的三个层次中，'趋势信号'指的是什么？",options:["能直接看到的异常结果，如回款下跌", "数据走势中隐藏的预警，如通话时长逐周递减", "已经爆发的严重事故", "上级明确提出需要整改的问题"],answer:1,explanation:"趋势信号介于表面现象和潜在风险之间，是数据走势中隐藏的预警信号。比如员工通话时长逐周递减，虽然绝对值还没出问题，但趋势已经在发出警告。"},
{id:129,competencyId:6,stem:"在5 Why分析法中，追问应该停止在什么程度？",options:["问满五个为什么就停止", "只问到第二个为什么就够了", "找到的原因可控且可改变为止", "员工回答不上来就停止"],answer:2,explanation:"5 Why分析法的核心不是必须问满5次，而是坚持问到根因层面——即找到的原因必须是可控的、可改变的。如果第三层就找到了这样的根因，可以停止；如果第五层还没找到，继续追问。"},
{id:130,competencyId:6,stem:"鱼骨图（因果图）的六大分析维度（5M1E）中，'法（Method）'指的是什么？",options:["法律法规和合规要求", "工作流程、制度规范、操作方法", "法术和技巧", "法院判决和裁定"],answer:1,explanation:"5M1E中'法（Method）'指工作流程、制度规范、操作方法、话术技巧等。当分析问题原因时，需要检查现有的流程和方法是否存在缺陷或不合理之处。"},
{id:131,competencyId:6,stem:"主任发现组员回款率突然下降，以下哪个做法最符合'问题识别'的正确思路？",options:["立即找该组员谈话，要求其限期改善", "从数据、行为、情绪、流程四个维度全面观察后再下判断", "在团队会议上公开通报该数据，形成压力", "暂时不管，看下周数据能否自然恢复"],answer:1,explanation:"问题识别的正确姿势是：不急于下判断，先用四维度（数据、行为、情绪、流程）全面观察。回款下降只是表象，可能根因在情绪波动、流程卡点、或者个人遇到了困难。"},
{id:132,competencyId:6,stem:"以下哪项描述最准确地概括了管理者在问题识别中的核心原则？",options:["关注绝对值，KPI低于目标线时立即介入", "关注异常变化，小异常是大问题的前兆", "等到问题明显了再集中力量解决", "关注竞争对手的做法，对标处理"],answer:1,explanation:"核心原则是关注'异常变化'而非'绝对值'。绝对值跌破红线时问题已经很大了，真正的管理功夫在于能在苗头阶段就识别出趋势信号。"},
{id:133,competencyId:6,stem:"问题识别的四个观察维度包括哪些？",options:["数据维度：业绩指标、过程指标、合规指标的异常波动", "行为维度：员工工作习惯、沟通方式、出勤状态的突然变化", "情绪维度：团队氛围、员工情绪、协作态度的微妙转变", "家庭维度：员工的家庭背景和经济状况"],answer:0,explanation:"四个观察维度是：数据维度、行为维度、情绪维度、流程维度。家庭维度不是管理者应该重点关注的方向，属于个人隐私范畴。"},
{id:134,competencyId:6,stem:"使用5 Why分析法时，以下哪些做法是正确的？",options:["每一层答案作为下一层问题的起点，层层深入", "问到第五层不论找到什么原因都立刻停止", "保持追问到找到可控、可改变的根因为止", "验证确认找到的根因是不是真的根本原因"],answer:0,explanation:"5 Why的正确用法是层层递进直到找到可控可改变的根因，并进行验证确认。不是机械地问满5次就停，也不是问到自己满意就停。"},
{id:135,competencyId:6,stem:"鱼骨图分析的5M1E六大维度包括哪些？",options:["人（Man）——技能、态度、沟通", "钱（Money）——薪酬、奖金、成本", "机（Machine）——系统、工具、设备", "法（Method）——流程、制度、话术方法"],answer:0,explanation:"5M1E六大维度是：人(Man)、机(Machine)、料(Material)、法(Method)、环(Environment)、测(Measurement)。钱(Money)不是标准维度。"},
{id:136,competencyId:6,stem:"用5 Why分析法时，连续追问'为什么'往往会让员工感到像审问，因此管理者应该用'我们一起来看看'的合作姿态，让员工自己说出答案。",options:["正确", "错误"],answer:0,explanation:"正确。5 Why的关键不是追问本身，而是追问的姿态。如果管理者用的是审问式语气（'你为什么这么做？''那又是因为什么？'），员工会产生防御。应该用合作式姿态（'我们一起梳理一下''你觉得往下看是什么原因？'），让员工参与分析过程。"},
{id:137,competencyId:6,stem:"发现团队数据异常时，管理者的第一反应应该是立即找到责任人进行问责。",options:["正确", "错误"],answer:1,explanation:"错误。第一反应不应该是追责，而应该了解情况。追责文化会导致员工隐瞒问题，让管理者更加看不见真实情况。正确的第一反应是'我注意到数据有变化，想了解发生了什么'——信号发现后才进入根因分析。"},
{id:138,competencyId:6,stem:"鱼骨图适用于单一原因导致的问题分析，对于多因素交织的复杂问题不太适用。",options:["正确", "错误"],answer:1,explanation:"错误。鱼骨图恰好相反——它适用于涉及多因素的复杂问题分析。通过5M1E六大维度系统梳理所有可能的原因，非常适合多因素交织的情况。对于单一原因问题，直接用5 Why就够了。"},
{id:139,competencyId:6,stem:"老员工小王突然业绩暴跌，主任第一反应认为'他肯定是松懈了'，这种归因方式符合问题识别的正确方法。",options:["正确", "错误"],answer:1,explanation:"错误。急于归因到'员工态度问题'是管理者常见的第一反应偏差。正确做法是先做全面的四维度观察（数据、行为、情绪、流程），确认信息和信号，再进入分析环节。业绩暴跌可能是心理创伤、外部事件、能力瓶颈等多种因素导致的。"},
{id:140,competencyId:5,stem:"执行力的三个关键节点中，'启动期'最容易出现的问题是什么？",options:["动力衰减、热度消退", "冲刺心态崩盘、质量下降", "理解偏差、方向跑偏", "资源不足、预算超支"],answer:2,explanation:"启动期（前3天）最常出现理解偏差——管理者以为自己说清楚了，但每个人理解到的版本不一样。关键动作是复述确认和示范标准做法。"},
{id:141,competencyId:5,stem:"纠偏机制的黄金法则中，'越快越好'是什么意思？",options:["出了问题当天就要完成全部纠偏流程", "发现偏离的第一天就介入，别等'再看看'", "所有纠偏都必须在周会之前完成", "发现问题后必须在1小时内找到根本原因"],answer:1,explanation:"'越快越好'是指偏离的第一天就要介入，不要让小偏差积累成大偏差。很多人会想'先观察两天'，但偏差有滚雪球效应——今天的10%偏离不处理，三天后可能变成30%。"},
{id:142,competencyId:5,stem:"管理者在纠偏谈话中，应该聚焦在什么上？",options:["为什么你没做好——帮员工认识到错误", "接下来怎么做好——帮员工找到改进路径", "别人为什么能做好——树立榜样制造压力", "如果做不好会怎样——让员工产生紧迫感"],answer:1,explanation:"纠偏的黄金法则之一是'聚焦未来'。不要纠结'你为什么没做好'，而是聚焦'接下来怎么做好'。分析原因是手段，解决方案才是目的。"},
{id:143,competencyId:5,stem:"在过程管控中，管理者最应该重点检查的是什么？",options:["所有环节都平均分配检查时间", "所有员工都随机抽取检查", "最关键的那几个动作——承上启下、最容易出错、最能预测结果的节点", "月末最后一周集中检查所有过程和结果指标"],answer:2,explanation:"识别关键节点的标准：这个动作做完后面的动作才能开始（承上启下）、这个动作最容易出问题（历史犯错率高）、这个动作最能预测最终结果（领先指标）。关键节点要必查、必确认、必记录。"},
{id:144,competencyId:5,stem:"纠偏之后，管理者必须做的关键动作是什么？",options:["让员工写一份书面检讨", "在团队会议上通报纠偏结果", "设定下一次检查的时间节点", "将纠偏记录存档到员工档案"],answer:2,explanation:"纠偏的黄金法则之'纠偏之后必须有追踪'——每次纠偏必须带一个'下次检查时间'。纠偏不是纠完就完了，必须形成一个'纠偏→追踪→验证→再纠偏或确认改善'的闭环。"},
{id:145,competencyId:5,stem:"纠偏机制的三个层次包括哪些？",options:["轻度纠偏：适用于偶尔轻微偏离，方式为私下简短提醒", "中度纠偏：适用于连续3天以上偏离，方式为正式一对一谈话", "重度纠偏：适用于持续偏离且影响整体目标，方式为正式面谈+书面记录+改善计划", "开除纠偏：适用于任何偏离，直接清退"],answer:0,explanation:"三个纠偏层次：轻度（日常提醒，私下简短）、中度（结构化反馈，正式一对一）、重度（正式干预，书面记录+改善计划+未达标后果）。层级升级取决于偏离的持续时间和影响程度。"},
{id:146,competencyId:5,stem:"纠偏的黄金法则包括哪些？",options:["越快越好——发现偏离第一天就介入", "先问后说——先让员工自己说原因，你再给判断", "聚焦未来——讨论'接下来怎么做好'而非'你为什么没做好'", "对事不对人——针对具体行为和结果，不上升为态度和能力评价"],answer:0,explanation:"纠偏五大黄金法则：越快越好、先问后说、聚焦未来、对事不对人、纠偏之后必须有追踪。全部适用。"},
{id:147,competencyId:5,stem:"执行中期（第1-2周），管理者维持团队动力的关键动作包括哪些？",options:["用数据反馈维持动力：每天让团队看到进度变化", "树立标杆：让做得好的分享方法而非单纯表扬", "解决障碍：员工遇到的困难管理者第一个冲上去帮忙", "加大惩罚：对动力不足的员工直接降薪以示警戒"],answer:0,explanation:"维持执行动力靠正向反馈：数据可视化、标杆分享方法、主动帮团队解决障碍。靠惩罚维持动力的做法会适得其反——中期动力衰减是自然规律，需要的是节奏感和成就感，而非恐惧感。"},
{id:148,competencyId:5,stem:"纠偏应该当众进行，以起到杀鸡儆猴的效果。",options:["正确", "错误"],answer:1,explanation:"错误。轻度纠偏应该私下进行。当众批评会激活员工的防御机制，导致纠偏对话变成情绪对抗。除非是重度纠偏需要正式记录，正常情况下纠偏应在一对一、私下、安全的环境中进行。"},
{id:149,competencyId:5,stem:"'你最近态度不太好'是一个有效的纠偏表述，因为它直接点出了核心问题。",options:["正确", "错误"],answer:1,explanation:"错误。'态度不好'是典型的无效纠偏——太笼统，员工不知道具体要改什么。纠偏要具体到行为：'你连续三天早上的第一通电话都在9:30以后，明天开始9:00之前完成至少3通有效通话'。"},
{id:150,competencyId:5,stem:"在检查和追踪过程中，看数据的趋势变化比看数据的绝对值更有预警价值。",options:["正确", "错误"],answer:0,explanation:"正确。绝对值跌破红线时问题已经比较大了。连续三天的下降趋势就是预警信号——这才是管理者最该关注的时刻。更关键的是看「指标组合」而非单一指标：通话量降了但回款没降，可能说明员工在精准打击而非偷懒。"},
{id:151,competencyId:5,stem:"执行力管控就是月底前检查计划是否完成，中间的过程由执行者自己掌控。",options:["正确", "错误"],answer:1,explanation:"错误。月底检查已经来不及了。执行力管控的核心是过程追踪——建立日/周/月的检查节奏，在关键节点上及时纠偏。管控不是不信任团队，而是确保方向不跑偏、障碍不过夜。"},
{id:152,competencyId:5,stem:"主任接到公司目标'本月回款提升15%'后，以下哪个做法最能体现目标解码的正确思路？",options:["直接在晨会上宣布目标，要求大家努力", "将15%分解为每人每天需要多做的具体动作", "只告诉核心骨干，让他们带头完成", "等上级给出了更详细的执行方案再传达"],answer:1,explanation:"目标解码的核心是把模糊的目标翻译成每个人每天的明确动作。15%→每人日均多打5通电话、多挖掘1个意向客户，这样组员才知道明天早上9点具体做什么。"},
{id:153,competencyId:5,stem:"SMART原则中，字母A（Achievable）的正确含义是什么？",options:["目标越高越好，挑战极限", "目标应该轻松完成，不给团队压力", "目标应该有挑战但跳一跳够得着", "目标只要领导觉得合理就行"],answer:2,explanation:"A-Achievable（可实现的）意味着目标有挑战但通过努力可以达成。太低了没挑战（团队觉得被低估），太高了团队直接放弃（'反正完不成'）。一般建议在现有水平上提升20-30%为佳。"},
{id:154,competencyId:5,stem:"目标分解的三个层次从高到低依次是什么？",options:["行动目标→过程目标→结果目标", "结果目标→过程目标→行动目标", "过程目标→结果目标→行动目标", "行动目标→结果目标→过程目标"],answer:1,explanation:"三个层次自上而下：结果目标（月回款20万）→ 过程目标（日均有效通话50通、日均意向客户3个）→ 行动目标（每天早上9:00-11:00拨打25通电话）。不能只分解到结果目标就停了。"},
{id:155,competencyId:5,stem:"以下哪个SMART目标写得最符合标准？",options:["尽快提高回款率，力争本月有明显改善", "5月底前，人均日回款额从2000元提升到3000元，每天多挖掘1个意向客户", "本月大家加油干，争取超额完成目标", "提高客户满意度，减少投诉数量"],answer:1,explanation:"选项1缺少可衡量性和时限性；选项3太笼统；选项4不够具体。选项2包含了具体的数字（从2000到3000）、可衡量的标准、明确的时间（5月底前）和具体的行动路径（每天多挖掘1个意向客户）。"},
{id:156,competencyId:5,stem:"主任向下传达目标时，做了目标测算——20万÷10人=人均2万，比上月人均1.5万多5000。这个测算属于目标解码的哪一步？",options:["翻译目标：将公司语言翻译成团队语言", "理解目标：做目标背后的计算和逻辑分析", "分解行动：将每个员工的每日行动列出来", "汇报目标：对上对齐目标可行性"],answer:1,explanation:"目标解码三步法第一步就是'理解目标'——做目标测算，搞清楚目标从哪里来、数字是否成立。如果主任自己都不相信目标能达成，团队更不会相信。"},
{id:157,competencyId:5,stem:"目标定了却完不成的五个常见根因包括哪些？",options:["目标模糊：'提高回款率'——没说到什么程度、什么时候", "目标脱离实际：不考虑团队能力和资源配置，拍脑袋定目标", "只定目标不给路径：把目标一扔，让员工自己想办法", "员工能力太差：团队整体素质达不到要求"],answer:0,explanation:"五个常见根因是：目标模糊、目标脱离实际、只定目标不给路径、缺乏过程追踪、目标与执行脱节。'员工能力太差'是一种回避管理责任的归因方式——如果员工能力真不够，恰恰需要目标分解和过程辅导来弥补。"},
{id:158,competencyId:5,stem:"SMART原则包含哪些要素？",options:["S-Specific（具体的）", "M-Measurable（可衡量的）", "A-Achievable（可实现的）", "R-Relevant（相关的）和 T-Time-based（有时限的）"],answer:0,explanation:"SMART五个要素是：Specific（具体的）、Measurable（可衡量的）、Achievable（可实现的）、Relevant（相关的）、Time-based（有时限的），缺一不可。"},
{id:159,competencyId:5,stem:"目标解码三步法包括哪些步骤？",options:["理解目标背后的'为什么'，做目标测算", "将公司语言翻译成团队能懂的日常语言", "将团队目标分解为每个人每天的明确行动", "制定考核方案和奖惩机制"],answer:0,explanation:"目标解码三步法：理解目标→翻译目标→分解为行动。考核方案和奖惩机制不是目标解码的核心环节，而是配套的管理工具。"},
{id:160,competencyId:5,stem:"主任接到公司目标后直接转述给团队，不做任何加工，这样最快最高效。",options:["正确", "错误"],answer:1,explanation:"错误。这是'目标传声筒'误区。不做解码直接传达的结果是团队听到的只有模糊的数字而没有清晰的路径。主任的价值之一就是把公司目标解码为团队能理解和执行的行动方案。"},
{id:161,competencyId:5,stem:"目标分解应该分解到'行动目标'层面而不仅是'结果目标'层面，因为行动目标是员工每天能直接执行的最小单元。",options:["正确", "错误"],answer:0,explanation:"正确。检验标准是：组员明天早上9点能不能不经过思考就知道自己第一个动作是什么。如果只分解到结果目标（月回款2万），组员仍然不知道怎么行动；分解到行动目标（每天早上9-11点拨出25通电话），组员才知道具体该做什么。"},
{id:162,competencyId:5,stem:"SMART原则中的R（Relevant）只关注目标是否和岗位有关，不需要考虑该目标对其他目标的贡献。",options:["正确", "错误"],answer:1,explanation:"错误。Relevant不仅要求目标与岗位职责相关，还要考虑这个目标对整体目标链条的贡献。例如，催收员学数据分析是相关的（帮他提高效率），但学做Excel艺术字是不相关的。"},
{id:163,competencyId:5,stem:"月度目标定了之后，每周检查一次就够了，中间不需要额外的追踪。",options:["正确", "错误"],answer:1,explanation:"错误。等月底看结果才发现差距40%已经来不及了。必须建立至少每周一次的进度检查机制，对于关键任务甚至需要每日检查。过程管控的频率要和任务的重要程度和紧急程度匹配。"},
{id:164,competencyId:2,stem:"根据沟通漏斗原理，主任心里想清楚的内容经过逐级传递后，下属最终能准确执行的比例大约是多少？",options:["大约80%", "大约60%", "大约50%", "大约40%"],answer:3,explanation:"沟通漏斗指出：主任心里想100%，嘴上说80%，下属听到60%，真正执行的只有40%。这是信息在逐级传递中不断衰减的结果，必须用方法对抗漏斗效应。"},
{id:165,competencyId:2,stem:"清晰派活四步法的第一步是明确Who与When，即确定责任人和时间节点。",options:["正确", "错误"],answer:1,explanation:"第一步应该是说明Why（目的）与What（目标），先讲清楚为什么要做、要交付什么结果，再确定Who与When。先统一思想和标准，再定责任和节点。"},
{id:166,competencyId:2,stem:"在布置催收任务时，组长对组员说'这批案子你跟一下'。根据清晰派活四步法，这句话存在的主要问题是什么？",options:["没有明确时间节点", "没有说明Why和What，下属缺少判断依据和执行标准", "没有确认下属是否听懂", "没有提供协催资源"],answer:1,explanation:"这句话缺失了Why（为什么要跟这批案子）和What（要达到什么效果、交付什么结果），属于典型的'只说做什么不说为什么'的错误。下属遇到意外情况时不知道如何判断和处理，容易执行跑偏。"},
{id:167,competencyId:2,stem:"高效听报三要素要求主任在听取下属汇报时，重点关注以下哪些方面？",options:["听事实，而非情绪", "听困难，而非借口", "听方案，而非只抛问题", "听态度，而非业绩"],answer:0,explanation:"高效听报三要素是：听事实而非情绪（识别情绪信号，拉回客观事实）、听困难而非借口（区分真困难和假借口）、听方案而非只抛问题（要求员工带着初步想法来汇报）。"},
{id:168,competencyId:2,stem:"下属汇报时说：'这个客户太烦了，每次打电话都说没钱，完全没办法。'这段话中包含了哪些情绪信号？",options:["只有模糊词汇", "只有夸张形容词", "夸张形容词和以偏概全", "模糊词汇和客观事实"],answer:2,explanation:"'太烦了''完全没办法'属于夸张形容词；'每次'属于以偏概全。这两种情绪信号叠加，说明下属已经被情绪主导，主任需要用'共情→引导→转向'三步法将其拉回事实层面。"},
{id:169,competencyId:2,stem:"面对下属的情绪化汇报，主任应先共情接纳情绪，再用5W2H框架将话题拉回事实层面，最后总结事实推进分析。",options:["正确", "错误"],answer:0,explanation:"这正是'共情→引导→转向'三步法的正确流程。先共情（接纳情绪），再引导（用5W2H把情绪转化为事实），最后转向（总结事实，推进分析），而不是直接反驳情绪或跟着情绪走。"},
{id:170,competencyId:2,stem:"以下哪些属于'共情→引导→转向'三步法中'引导'环节的正确做法？",options:["我完全理解你的挫败感，这个客户确实不好处理", "客户具体是哪一天、通过什么方式答应还款的？当时承诺的金额是多少？", "所以我们现在面对的情况是客户承诺后又拖延了三次，你觉得核心原因是什么？", "从承诺日到现在，他一共拖延了几次？每次给出的理由分别是什么？"],answer:1,explanation:"A选项属于共情环节（接纳情绪），C选项属于转向环节（总结事实后推进分析）。B和D选项属于引导环节，通过5W2H追问具体事实，将情绪转化为可分析的具体信息。"},
{id:171,competencyId:2,stem:"下属反映'这批案子根本就联系不上，没办法了'，根据真困难与假借口的四象限判断，这最可能属于哪种类型？",options:["外部归因型借口", "笼统概括型借口", "真困难（能力/资源不足）", "真困难（意愿/态度问题）"],answer:1,explanation:"'联系不上''没办法'属于笼统概括型借口，缺乏具体细节。主任应该用5W2H追问具体场景：打了多少次？分别是什么时段？是否用了不同号码？是否有换时间再打？帮助下属拆解到可执行的具体动作。"},
{id:172,competencyId:2,stem:"任务布置完后，主任应该问下属'都清楚了吗？'来确认双方理解一致。",options:["正确", "错误"],answer:1,explanation:"这是常见误区。问'都清楚了吗？'下属通常会回答'清楚了'，但实际可能并未真正理解。正确的做法是让下属主动复述关键点，如'你花30秒跟我复述一下：这个任务最关键的目标是什么？'"},
{id:173,competencyId:2,stem:"在清晰派活四步法的Check（复述确认）环节，以下哪种确认方式最有效？",options:["你听懂了吗？", "都清楚了吗？还有没有问题？", "你花30秒跟我复述一下：这个任务最关键的目标和你最需要我支持的一点分别是什么？", "我讲明白了吗？"],answer:2,explanation:"让下属主动复述关键信息，是验证真实理解程度最有效的方式。永远不要假设下属理解了，要主动去验证。'你听懂了吗'或'都清楚了吗'这类封闭式问题无法暴露理解偏差。"},
{id:174,competencyId:2,stem:"以下哪些属于主任在布置任务与听取汇报时的常见误区？",options:["只讲做什么不讲为什么，下属缺少判断依据", "让下属主动复述关键任务目标来验证理解", "听汇报时被情绪带着走，陷入一起抱怨", "替下属解决所有问题，导致下属产生依赖"],answer:0,explanation:"B选项（让下属主动复述）是正确做法，不是误区。A选项缺失Why信息、C选项被情绪带走、D选项替代下属思考，都是常见误区。正确做法是：先讲Why再讲What，共情后拉回事实，要求下属带方案讨论。"},
{id:175,competencyId:2,stem:"当员工汇报时只抛问题（如'客户说要投诉'），主任应当立刻帮员工分析情况并给出解决方案。",options:["正确", "错误"],answer:1,explanation:"主任不应做'救火队长'替下属解决所有问题。正确做法是先问'你的想法是什么？''如果由你来决定，下一步你会怎么做？'，培养下属独立思考和解决问题的能力，而不是让管理者越来越忙。"},
{id:176,competencyId:2,stem:"绩效面谈的本质是什么？",options:["对员工上一阶段表现的评判和打分", "实现'回顾过去、分析现状、规划未来'三重目标的双向沟通", "管理者向员工传达公司要求和指标", "对低绩效员工的警告和改进通知"],answer:1,explanation:"绩效面谈的本质是通过深度交流，实现'回顾过去、分析现状、规划未来'的三重目标，最终推动员工个人成长与组织绩效提升的协同统一，而非单一的业绩评判。"},
{id:177,competencyId:2,stem:"针对高绩效员工，绩效面谈的重点应该是什么？",options:["发现问题、分析原因、基础技能提升", "激励保留、挑战更高目标、邀请分享经验", "警告其不要骄傲自满", "与其他员工进行横向比较"],answer:1,explanation:"对于高绩效员工，面谈重点应该是激励保留、挑战更高目标、分享经验——充分认可其贡献，探讨职业发展路径，邀请担任内部导师。"},
{id:178,competencyId:2,stem:"ART法则中，哪个阶段的时间分配应该最多（占比40%）？",options:["A（Assessment）评估阶段", "R（Reflection）反思阶段", "T（Target）目标阶段", "三个阶段应该平均分配"],answer:2,explanation:"ART法则建议时间分配：A（评估）25%、R（反思）35%、T（目标）40%。反思和目标才是重点，体现了'帮助者而非审判者'的心态。"},
{id:179,competencyId:2,stem:"BIC有效反馈模型中，B代表什么？",options:["Belief——信念和价值观", "Behavior——具体的行为描述", "Benefit——好处和收益", "Balance——平衡和折中"],answer:1,explanation:"BIC模型：B=Behavior（行为），描述具体可观察的行为，做到'对事不对人，时间/地点/事件清晰'；I=Impact（影响）；C=Consequence（后果）。"},
{id:180,competencyId:2,stem:"以下哪句话最符合BIC模型中对B（行为）的描述要求？",options:["你态度太差了", "你今天没有认真工作", "在今天上午10点与债务人张三的通话中，当他表示经济困难时，你连续三次打断了他的发言", "你最近的表现一直不好"],answer:2,explanation:"B（行为）的要求是'对事不对人，时间、地点、事件清晰'。选项3包含了具体时间（上午10点）、对象（张三）、场景（表示经济困难时）、行为（连续三次打断），完全符合要求。"},
{id:181,competencyId:2,stem:"ART法则的A（评估）阶段，开场定调应该营造什么样的氛围？",options:["严肃、正式、强调后果", "坦诚、建设、基于事实", "轻松、随意、避免谈数据", "高压、紧迫、要求员工认错"],answer:1,explanation:"A阶段的开场定调应营造坦诚、建设的氛围，基于客观事实而非主观感觉。核心动作是数据说话、先听后说——让员工先做自我评估。"},
{id:182,competencyId:2,stem:"绩效面谈结束后，以下哪项是最容易被忽视但最关键的动作？",options:["整理面谈纪要和制定IDP追踪计划", "向上级汇报面谈结果", "在团队会议上通报面谈情况", "与HR确认绩效评级"],answer:0,explanation:"课程强调'只面谈不跟进=0'。面谈结束后需要在T日内整理面谈纪要发送员工确认、制定IDP（个人发展计划）、设立周期检查点、兑现承诺的支持。"},
{id:183,competencyId:2,stem:"GROW模型更适合用于哪种场景？",options:["对重大违规的严肃处理", "员工遇到瓶颈、需要创意或为长远目标制定计划时", "绩效考核不达标的惩罚沟通", "团队裁员和人员调整"],answer:1,explanation:"GROW模型更侧重于员工发展、教练式辅导和解决问题。当员工遇到瓶颈、需要创意、或为长远目标制定计划时，GROW非常有效。"},
{id:184,competencyId:2,stem:"绩效面谈的'四性'特征包括哪些？",options:["针对性——聚焦具体绩效数据和行为表现", "双向性——管理者和员工共同参与对话", "惩罚性——对不足之处进行必要的惩罚和问责", "发展性——目标是未来改进和成长"],answer:0,explanation:"绩效面谈的四性是：针对性、双向性、发展性、正式性。'惩罚性'不是绩效面谈的特征——面谈的目的是帮助与改进，而非惩罚。"},
{id:185,competencyId:2,stem:"以下关于BIC有效反馈模型的描述，正确的有哪些？",options:["B（行为）要做到对事不对人，时间、地点、事件清晰", "I（影响）让对方理解'为什么这是个问题'", "C（后果）应该与个人利益或团队目标相关联", "在C之后应自然过渡到商讨解决方案，可衔接GROW模型"],answer:0,explanation:"以上四项全部正确。BIC模型的核心是借事实、指影响、明后果，并在C之后自然转向行动方案，让反馈指向未来而非追究过去。"},
{id:186,competencyId:2,stem:"针对低绩效员工，绩效面谈应该注意哪些方面？",options:["具体指出问题，用数据说话", "提供结构化指导而非笼统要求", "建立频繁跟进机制而非一次面谈了事", "在公开场合进行以起到警示作用"],answer:0,explanation:"低绩效员工面谈应该：具体指出问题+数据说话、提供结构化指导、建立频繁跟进机制。绝不应在公开场合进行——面谈应在私密环境一对一进行。"},
{id:187,competencyId:2,stem:"ART法则中，管理者应该秉持'审判者'的心态，对员工的不足之处做出公正的评判。",options:["正确", "错误"],answer:1,explanation:"错误。ART法则的心态基础是秉持'帮助者'而非'审判者'的心态。绩效面谈的目标是帮助员工改进和发展，而非审判过去的行为。"},
{id:188,competencyId:2,stem:"绩效面谈中，对高绩效和低绩效员工可以使用完全相同的面谈策略和话术。",options:["正确", "错误"],answer:1,explanation:"错误。不同绩效水平需要差异化策略：高绩效→激励保留+挑战更高目标；稳定绩效→突破瓶颈+渐进目标；低绩效→具体指导+频繁跟进。'一刀切'的沟通方式会适得其反。"},
{id:189,competencyId:2,stem:"BIC反馈的初衷是批评和追责，以帮助员工认识到自己的错误。",options:["正确", "错误"],answer:1,explanation:"错误。BIC的灵魂是给予反馈的初衷是帮助与改进，而非批评。保持语气平和，陈述事实，在C之后自然过渡到商讨解决方案——这才是BIC的正确应用。"},
{id:190,competencyId:2,stem:"GROW教练式辅导模型的四个步骤，正确的顺序是什么？",options:["Goal目标 → Options选择 → Reality现状 → Will行动", "Goal目标 → Reality现状 → Options选择 → Will行动", "Reality现状 → Goal目标 → Options选择 → Will行动", "Goal目标 → Reality现状 → Will行动 → Options选择"],answer:1,explanation:"GROW模型的标准顺序是：G（Goal）设定目标 → R（Reality）梳理现状 → O（Options）探索选择 → W（Will）确定行动。先明确目标，再基于现状找方案，最后落实到具体行动。"},
{id:191,competencyId:2,stem:"ART法则中，A（Assessment评估现状）环节应占绩效面谈时间的50%以上。",options:["正确", "错误"],answer:1,explanation:"ART法则的时间分配是：A占25%，R（反思探索）与T（目标规划）占75%。反思和目标规划才是面谈的重点，评估现状只是拉齐认知的起点，不应占用过多时间。"},
{id:192,competencyId:2,stem:"在使用ART法则进行月度绩效面谈时，员工上季度回收率达105%但首催成功率低于团队均值。主任第一步应该怎么做？",options:["直接指出首催成功率低的问题并要求改正", "先让员工做自我评估，再说出自己的观察", "跳过评估直接制定下月改进计划", "以表扬回收率为主，不提首催成功率的问题"],answer:1,explanation:"ART法则的A环节强调'先听后说'——让员工先做自我评估，再给出反馈。这样既能了解员工的自我认知，又能避免单向输出导致员工防御。正确话术如：'你自己怎么看待这个结果？你认为最大的亮点和最大的挑战分别是什么？'"},
{id:193,competencyId:2,stem:"BIC有效反馈模型的三个构成要素包括哪些？",options:["Behavior 行为", "Belief 信念", "Impact 影响", "Consequence 后果"],answer:0,explanation:"BIC模型由三部分组成：B（Behavior）描述具体可观测的行为，包含时间、地点、情境；I（Impact）说明该行为带来的直接后果；C（Consequence）关联更广层面的长期影响，并转向未来的改进。"},
{id:194,competencyId:2,stem:"BIC模型中的C（Consequence后果）指的是行为带来的即时、可见的直接后果。",options:["正确", "错误"],answer:1,explanation:"BIC模型中，I（Impact影响）说的是即时、可见的直接后果，例如导致客户投诉、失去协商机会等；而C（Consequence后果）则是更广层面的长期影响，如影响绩效考核、团队协作效能等。"},
{id:195,competencyId:2,stem:"主任对催收员小李说：'今天上午10点与客户王先生的通话中，当他第三次表示经济困难时，你提高了音量说'你别找借口了'。'这属于BIC模型中的哪个环节？",options:["Behavior 行为", "Impact 影响", "Consequence 后果", "同时包含B和I"],answer:0,explanation:"这句话描述了具体的时间（今天上午10点）、人物（客户王先生）、情境（第三次表示经济困难时）和具体行为（提高音量说'你别找借口了'），属于B环节——锚定具体可观测的行为，而不是对人格做评价。"},
{id:196,competencyId:2,stem:"针对高绩效员工，绩效面谈的核心策略是什么？",options:["教练辅导，制定PIP改进计划并高频追踪", "激励保留，设定更高目标并赋予标杆角色", "批评指正，防止骄傲自满", "维持现状，不做过多干预"],answer:1,explanation:"高绩效员工的面谈策略是激励保留：设定更高目标（职业发展、职级晋升、绩效突破），树立为团队标杆，赋予B角/C角、小组长、辅导讲师等角色，让他们持续成长并带动团队。"},
{id:197,competencyId:2,stem:"针对稳定绩效员工的绩效面谈，以下哪些做法是正确的？",options:["肯定其工作态度与现有成果", "发掘潜力点，帮助解决卡点", "要求离职或转岗", "利用其长处带动他人，如担任带教新人角色"],answer:0,explanation:"稳定绩效员工的面谈策略是激发突破：肯定工作态度与现有成果，发掘潜力点解决卡点，利用其长处带动他人（如担任氛围官、带教新人）。制定PIP计划是针对低绩效员工的策略。"},
{id:198,competencyId:2,stem:"面谈后的追踪机制中，只需要在面谈结束当天整理纪要并发给员工确认即可，无需建立台账和定期检查。",options:["正确", "错误"],answer:1,explanation:"面谈仅完成50%，后续追踪决定成败。完整的追踪机制包括：T日内发送纪要确认、建立台账记录每次面谈、制定IDP个人发展计划、3天/7天后定期检查、兑现支持承诺、与绩效关联。只面谈不跟进等于零。"},
{id:199,competencyId:2,stem:"以下哪一项不属于绩效面谈后追踪六步机制的内容？",options:["T日内整理面谈纪要，通过内聊发送给员工确认", "用Excel建立台账，记录每次面谈的时间、对象、结论、行动项", "将面谈结果在全团队范围内公示", "制定IDP个人发展计划，明确每日/每周需提交的验证材料"],answer:2,explanation:"将面谈结果公示全团队不属于追踪六步机制。六步机制包括：纪要确认、建立台账、制定IDP、定期检查（3天/7天）、兑现支持、绩效关联。面谈内容应保护员工隐私，不应公开公示。"},
{id:200,competencyId:2,stem:"绩效面谈的本质是管理者对员工进行单向的业绩评价和批评指正。",options:["正确", "错误"],answer:1,explanation:"绩效面谈不是批评会，而是管理者帮助员工回顾过去、分析现状、规划未来的正式沟通。它有四大要素：针对性（聚焦具体KPI）、双向性（员工也能反馈）、发展性（核心是帮员工成长）、正式性（有固定安排和书面记录）。"},
{id:201,competencyId:2,stem:"以下哪些属于绩效面谈中的常见误区？",options:["面谈时管理者单向输出评价，员工被动接受", "用BIC模型锚定具体行为进行反馈", "面谈结束后没有后续跟进，员工认为管理者只是说说而已", "对所有绩效层级的员工使用同一套面谈方式"],answer:0,explanation:"三个常见误区：单向输出评价（应让员工先自我评估），面谈后不跟进（应建立追踪台账），对所有员工用同一套方式（应区分高/稳/低绩效差异化策略）。B选项使用BIC锚定具体行为是正确的反馈方式，不属于误区。"},
{id:202,competencyId:1,stem:"SMART原则中的S代表什么含义？",options:["Specific（具体的）——目标必须明确清晰", "Simple（简单的）——目标不能太复杂", "Standard（标准的）——目标要符合规范", "Strategic（战略的）——目标要有战略高度"],answer:0,explanation:"S=Specific，目标必须具体明确，让下属能准确复述。比如不是'多打电话'而是'每日手动拨打15次有效联系'。"},
{id:203,competencyId:1,stem:"德鲁克提出的目标管理（MBO）核心理念是什么？",options:["先有目标，再有工作", "先有流程，再定目标", "目标跟随业务随时调整", "目标由上级单方面制定"],answer:0,explanation:"MBO的核心思想是'先有目标，再有工作'。企业的使命必须转化为具体目标，才能被有效执行。"},
{id:204,competencyId:1,stem:"效率（Efficiency）是把事情做对，效能（Effectiveness）是做对的事情。",options:["正确", "错误"],answer:0,explanation:"正确。效率关注方法，效能关注方向。管理者需要两者兼顾，但不能用战术上的勤奋掩盖战略上的懒惰。"},
{id:205,competencyId:1,stem:"以下哪个目标不符合SMART原则中的M（可衡量）？",options:["人均老案回收率提升3000元", "每日完成至少15次有效联系尝试", "大力提升催收效果", "接通率达到85%以上"],answer:2,explanation:"'大力提升催收效果'无法量化，没有具体数字指标。M=Measurable，必须有明确的数据指标可以追踪进度。"},
{id:206,competencyId:1,stem:"SMART目标制定的实战步骤包括哪些？（多选）",options:["识别问题现象", "直接给员工下达目标", "找到根因", "转化为SMART目标", "向员工传递目标"],answer:0,explanation:"四步实战：识别问题现象→找到根因→转化为SMART目标→向员工传递目标。不应该跳过诊断直接下目标。"},
{id:207,competencyId:1,stem:"'活动陷阱'（Activity Trap）指的是什么？",options:["团队活动组织得太少", "只顾低头拉车忙于日常事务，忘记了主要目标", "员工参加培训活动不够积极", "团队建设活动花费太多时间"],answer:1,explanation:"活动陷阱指管理者陷入忙碌的日常事务中，用行动替代思考，忘记了组织的主要目标是什么。"},
{id:208,competencyId:1,stem:"在SMART原则中，A（Achievable）意味着目标应该尽可能低，确保一定能完成。",options:["正确", "错误"],answer:1,explanation:"错误。A=可实现，意味着有挑战但非遥不可及。目标太低无法激发潜力，太高则打击士气。应基于当前数据设定合理提升幅度。"},
{id:209,competencyId:1,stem:"主任发现下属'连续3天使用一键外呼全量拨打，未聚焦重点案件'，这属于SMART实战步骤中的哪一步？",options:["找到根因", "识别问题现象", "转化为SMART目标", "向员工传递目标"],answer:1,explanation:"这是一个具体行为描述，属于识别问题现象这一步。需要进一步区分'工作积极性不高'（表象）vs'缺乏有效的案件分类方法'（根因）。"},
{id:210,competencyId:1,stem:"T（Time-bound）在SMART原则中的作用是什么？",options:["让员工知道目标有多难", "防止拖延，提供紧迫感和检查节点", "方便上级随时调整目标", "只是为了格式完整"],answer:1,explanation:"T=有时限，有明确完成期限才能防止拖延。例如'2026年3月3日—3月14日（两周）'，给出了清晰的起止时间。"},
{id:211,competencyId:1,stem:"以下哪些是SMART目标制定时的常见误区？（多选）",options:["只看结果不管过程", "目标模糊，用形容词代替数据", "放任绩优员工不管不问", "目标定得越高越好，不管是否能实现"],answer:0,explanation:"三大常见误区：①只看结果不管过程——缺少过程追踪；②目标模糊——'提升效果''加强跟进'等模糊表述；③放任绩优——认为绩优员工不需要管理。目标应既有挑战又可实现。"},
{id:212,competencyId:1,stem:"以下哪个是把模糊目标转化为SMART目标的正确做法？",options:["'加强客户跟进' → '每天下班前完成台账更新'", "'提升团队士气' → '每周开一次团建活动，不限形式'", "'降低投诉' → '本月重渠投诉控制在2单以内，每日检查敏感工单'", "'提高效率' → '让大家干活再快一点'"],answer:2,explanation:"选项③同时满足S（重渠投诉控制）M（2单以内）A（合理目标）R（与管理目标相关）T（本月+每日检查）。其他选项缺少关键要素。"},
{id:213,competencyId:1,stem:"在向员工传递目标时，只需要告诉员工'做什么'和'什么时候完成'即可。",options:["正确", "错误"],answer:1,explanation:"错误。传递目标还需要说明'为什么'（Why），让员工理解目标背后的逻辑和意义，才能激发内在动机，统一思想。"},
{id:214,competencyId:1,stem:"WBS（工作分解结构）在催收管理中最核心的价值是什么？",options:["帮主任记住所有业务流程和制度要求", "把复杂任务按逻辑层层分解成可分配、可追踪的小行动", "替代每日晨夕会，减少团队沟通成本", "自动生成数据报表，减少主任工作量"],answer:1,explanation:"WBS的核心价值是将复杂任务像拆乐高一样，按逻辑层层分解成可分配、可追踪的小行动，解决'目标有了但不知道从哪里下手'的问题。"},
{id:215,competencyId:1,stem:"在WBS分解四步法中，第一步'确定最终成果'的正确做法是什么？",options:["详细描述要完成的所有过程步骤", "明确任务完成的标准，描述结果而非过程", "列出所有可能遇到的困难和风险", "确定项目预算和执行时间表"],answer:1,explanation:"第一步不是描述过程，而是明确成果标准。例如在催收管理中，不是写'提升业绩'，而是明确'3月14日前，团队人均老案回收率提升3000元'这样的可衡量结果。"},
{id:216,competencyId:1,stem:"在315投诉风险防控案例中，按照WBS方法将'降低投诉'目标拆解后，属于'风险客户识别'模块下的具体执行动作是什么？",options:["每日晨会5分钟宣讲一个合规案例", "拨打前查客户小结，事前标签+事中安抚+事后上报", "联系法务部门进行合规知识培训", "整理每日催收台账并上报主任"],answer:1,explanation:"在315案例的WBS拆解中，风险客户识别的具体动作是：拨打前查客户小结（事前标签），通话中做好安抚（事中安抚），发现高风险及时上报（事后上报），形成可复制的SOP。"},
{id:217,competencyId:1,stem:"PDCA执行闭环中，'C'（检查）环节在催收管理中的具体动作是什么？",options:["用WBS拆解任务，用SMART设定目标", "按分解后的任务执行并记录催收台账", "晨夕会复盘数据，主任抽查台账和录音", "发现偏差立即纠正，更新下一轮执行计划"],answer:2,explanation:"PDCA中C（Check）环节的核心是定期检查执行偏差。在催收管理场景中，具体表现为晨夕会复盘数据、主任抽查台账和通话录音，确保执行不走偏。"},
{id:218,competencyId:1,stem:"WBS分解中'责任到人'原则的核心要求是什么？",options:["每项工作由团队全体成员共同负责", "每项工作有且只有一个主责人", "每项工作由主任亲自把关审批", "每项工作由组长分配给组员即可"],answer:1,explanation:"责任到人的核心是'每项工作有且只有一个主责人'，避免出现多人负责等于无人负责的情况。同时要配合检查节点（如一日三追、每日台账核查）确保落实。"},
{id:219,competencyId:1,stem:"WBS的三大优势包括哪些？",options:["化繁为简——将复杂任务拆解为可操作的工作包，降低执行难度", "责任到人——通过分工明确每项工作的责任人，便于追踪管理", "自动推进——分解后的任务会自动执行，减少管理干预", "避免遗漏——结构化梳理确保关键环节不被忽略"],answer:0,explanation:"WBS三大优势是：化繁为简（拆成可执行的小行动）、责任到人（每项工作有唯一主责人）、避免遗漏（结构化梳理防止漏项）。WBS不会自动推进任务，仍需主任跟进管理。"},
{id:220,competencyId:1,stem:"以下哪些属于WBS分解四步法的正确步骤？",options:["确定最终成果——明确任务完成的标准，描述结果而非过程", "识别主要模块——按时间逻辑（事前→事中→事后）或功能逻辑划分", "评估项目风险——识别所有潜在风险点并制定应急预案", "逐层分解与检查分配——拆到可执行的最小动作并责任到人"],answer:0,explanation:"WBS四步法是：①确定最终成果（明确What&Why）→②识别主要模块（按逻辑划分）→③逐层分解（剥洋葱式到最小动作）→④检查分配（查漏补缺+责任到人）。风险评估不属于WBS的固有步骤。"},
{id:221,competencyId:1,stem:"在315投诉风险防控案例中，运用WBS方法拆解后的执行方案包含哪些主要模块？",options:["合规前置宣导——法务宣讲+晨夕会专项宣传", "风险客户识别——拨打前查客户小结，事前事中事后闭环", "投诉赔偿处理——制定客户赔偿标准和安抚方案", "执行检查机制——每日巡检+敏感工单当日复听"],answer:0,explanation:"315案例WBS拆解的三个主要模块是：合规前置宣导（培训宣导）、风险客户识别（拨打前中后闭环）、执行检查机制（巡检+复听）。投诉赔偿处理是事后补救，不属于防控方案的主动模块。"},
{id:222,competencyId:1,stem:"WBS分解时，将任务分解到'合规宣导'这个层级就足够了，不需要继续往下拆到具体动作。",options:["正确", "错误"],answer:1,explanation:"错误。'分解到模块就停了'是常见的WBS误区。'合规宣导'只是一个模块名称，还需要继续拆解到具体动作，比如'每日晨会5分钟宣讲一个合规案例''本周组织一场法务专项培训'等可以立刻执行的最小动作。"},
{id:223,competencyId:1,stem:"在WBS分解后配合PDCA循环推进执行时，'A'（调整）环节指的是根据检查发现的问题及时调整策略，更新下一轮执行计划。",options:["正确", "错误"],answer:0,explanation:"正确。PDCA的A（Act）环节就是在检查（Check）发现问题后，对策略进行调整和优化，形成'计划→执行→检查→调整'的持续改进闭环，确保执行不打折。"},
{id:224,competencyId:1,stem:"'只分解不分配'是常见的WBS误区——即使有了详细的任务清单，但没人知道自己具体负责哪块，任务仍然无法真正落地。",options:["正确", "错误"],answer:0,explanation:"正确。WBS分解后每项任务必须有明确的主责人，且每项工作有且只有一个主责人。如果只有任务清单没有责任分配，就会出现'任务石沉大海'、相互推诿的情况。"},
{id:225,competencyId:1,stem:"在催收管理中应用WBS方法时，只需在月初列出整月的任务清单即可，日常执行中不需要再设立检查节点。",options:["正确", "错误"],answer:1,explanation:"错误。WBS分解后还必须建立检查节点来追踪执行情况，例如'一日三追''每日下班前台账核查'等。同时要配合PDCA循环，通过晨夕会复盘数据、抽查台账录音等方式确保执行到位，避免计划变成摆设。"},
{id:226,competencyId:1,stem:"催收组长李明刚晋升为主任后，发现自己每天仍花大量时间亲自打电话催收，组员业绩反而持续下滑。他最需要完成的核心转变是什么？",options:["从关注个人业绩产出转向关注团队整体目标的达成", "从现在开始完全停止打电话，只做行政管理工作", "从关注催收技巧转向关注Excel报表制作", "从对组员严格要求转向对组员无底线包容"],answer:0,explanation:"从骨干到管理者的核心转变是价值衡量标准的变化：从'个人业绩=个人价值'转向'团队业绩=管理价值'。李明的问题在于仍用骨干思维做主任工作，没有完成角色转型。"},
{id:227,competencyId:1,stem:"以下哪项最准确地描述了'效率'与'效能'在主任管理中的区别？",options:["效率是把事做对，效能是做对的事", "效率是做对的事，效能是把事做对", "效率关注团队成长，效能关注个人产出", "效率指速度快，效能指质量高"],answer:0,explanation:"效率（Efficiency）关注'把事做对'，即用更少的资源完成任务；效能（Effectiveness）关注'做对的事'，即选择正确的方向和目标。主任既要注重执行效率，更要优先确保方向正确。"},
{id:228,competencyId:1,stem:"主任工作'三板斧'中，'拿结果'环节的核心管理动作是什么？",options:["制定团队季度KPI指标", "过程管控、跟进追踪、及时纠偏", "招聘更多优秀催收员扩充团队", "每周向总监汇报工作进展"],answer:1,explanation:"'拿结果'是主任工作三板斧之一，核心是通过过程管控、跟进追踪、及时纠偏来确保目标达成，而非仅仅设定目标后就放手不管。"},
{id:229,competencyId:1,stem:"成熟主任三大核心价值中，'目标转化器'指的是什么？",options:["把公司目标分解为个人绩效考核指标", "把公司目标转化为团队可执行的行动", "把团队目标整理成PPT向上级汇报", "把个人目标与公司目标进行对齐"],answer:1,explanation:"'目标转化器'意味着主任要充当公司与团队之间的桥梁，将公司的战略目标转化为团队每个成员能够理解和执行的具体行动方案，而不仅仅是分解指标。"},
{id:230,competencyId:1,stem:"在'从专注事到关注人'的转型中，主任应该优先关注组员的哪些方面？",options:["只关注组员的业绩数据是否达标", "关注组员的心理状态、真实需求和职业发展", "关注组员是否服从管理指令", "关注组员的工作时长和考勤记录"],answer:1,explanation:"转型维度'从专注事到关注人'要求主任不仅关注业务产出，更要关注组员的心理状态、真实需求和职业发展。只有团队成长了，业绩才能持续提升。"},
{id:231,competencyId:1,stem:"从业务骨干到团队管理者，需要完成哪三个关键维度的转型？",options:["从'自己做'到'带着做'——学会合理授权和有效辅导", "从'专注事'到'关注人'——关注成员状态和职业发展", "从'关注业绩'到'搞好关系'——把团队氛围放在第一位", "从'线性思维'到'全局思维'——平衡短期与长期目标"],answer:0,explanation:"转型的三个关键维度是：从'自己做'到'带着做'（通过他人完成工作）、从'专注事'到'关注人'（关注团队成长）、从'线性思维'到'全局思维'（平衡短期与长期）。搞好关系是手段而非转型维度。"},
{id:232,competencyId:1,stem:"以下哪些属于主任常见的'五大转型误区'？",options:["事必躬亲——自己做得快，不放心交给组员", "只盯数字忽视人——只看KPI，不关注组员状态和成长", "严格考核绩效——坚持优胜劣汰的淘汰机制", "回避冲突当老好人——为维持表面和谐不敢直面矛盾"],answer:0,explanation:"五大转型误区包括：事必躬亲、只盯数字忽视人、回避冲突当老好人、不善向上沟通、忽视自我成长。严格绩效考核本身不是误区，关键在于是否同时关注人的发展。"},
{id:233,competencyId:1,stem:"成熟主任的三大核心价值包括哪些？",options:["目标转化器——把公司目标转化为团队可执行的行动", "问题解决者——及时发现和解决团队问题", "业绩贡献者——个人业绩在团队中保持TOP水平", "人才孵化器——培养和发展团队成员，输送优秀人才"],answer:0,explanation:"成熟主任的三大核心价值是：目标转化器（连接公司与团队）、问题解决者（发现并解决团队问题）、人才孵化器（培养输送人才）。个人业绩不再是主任的核心价值衡量标准。"},
{id:234,competencyId:1,stem:"催收主任老赵认为：'团队业绩不达标时，我先自己顶上，多打些电话把业绩拉起来。'这种以身作则的做法体现了正确的管理思维。",options:["正确", "错误"],answer:1,explanation:"这种想法是错误的。主任的价值在于'通过他人完成工作'，而不是自己亲自上阵。当业绩不达标时，主任应该分析问题根源（人员能力、名单质量、话术问题等），通过辅导和资源调配提升团队整体能力，而非自己替代组员干活。"},
{id:235,competencyId:1,stem:"五大转型误区中的'不善向上沟通'是指主任只管好自己一亩三分地，忽视与上级对齐，可能导致执行方向出现偏差。",options:["正确", "错误"],answer:0,explanation:"正确。不善向上沟通是五大转型误区之一，主任需要主动汇报工作进展、主动与上级对齐目标方向、主动为团队争取资源，确保团队的工作方向与公司整体战略一致。"},
{id:236,competencyId:1,stem:"管理者'事必躬亲'是值得提倡的工作态度，因为自己做最快最放心，能最大程度保证工作质量。",options:["正确", "错误"],answer:1,explanation:"错误。事必躬亲是五大转型误区之首。主任如果凡事亲力亲为，结果必然是'忙死自己，饿死组员'——组员得不到锻炼机会，能力无法提升，团队对主任的依赖性越来越强，形成恶性循环。正确做法是从小事开始授权，建立'授权-监督-反馈'闭环，容忍合理错误。"},
{id:237,competencyId:1,stem:"从'线性思维'到'全局思维'的转型，要求主任跳出单一执行视角，既能盯住短期业绩目标，又能兼顾团队的长期发展。",options:["正确", "错误"],answer:0,explanation:"正确。全局思维是转型三大维度之一，要求主任不再像骨干时期只关注自己的一亩三分地，而是以全局视野思考问题，在短期业绩压力和团队长期发展之间找到平衡点。"}
];
